INSERT INTO wdp_ai.reason_code (network, code, name, rulebook_edition, catalogue_version, grounds_header, how_to_read, terms_used, supplementary_header, agency_mccs, agency_mccs_reviewed, never_mention, banned_phrases) VALUES
  ('VISA', '13.1', 'Merchandise/Services Not Received', '18 April 2026', '1.5.0', 'Reason code {reasonCode} — the merchant''s permitted arguments: {codes}, in register order.', 'How to read this list. Each argument gives the rulebook''s words, then when to nominate it, the evidence that argues it most strongly, and when it does not fit. Nominate an argument whenever the merchant''s records bear on it, even if the evidence is not of the strongest kind: the rules decide later whether it is enough, and a missed argument costs the merchant more than an extra one. Always quote the record you rely on. Reject an argument only when it does not fit this case, or when nothing in the records bears on it. Every argument is listed on every case, but several apply only to one kind of sale or complaint: a remote sale, an in-person sale, an airline ticket, a service booked for a later date, a crypto or NFT purchase; judge from the records whether this case is that kind. The rule''s words govern the final decision; the lines below are deliberately broader, so that no argument is missed. The merchant''s pack is often one file holding many kinds of record: read all of it. Where a section of the case says an exclusion or limit is MET, rely on it: it was worked out from the record, not read from a document.', 'Terms used below.
INSERT INTO wdp_ai.reason_code (network, code, name, rulebook_edition, catalogue_version, grounds_header, how_to_read, terms_used, supplementary_header, agency_mccs, agency_mccs_reviewed, never_mention, banned_phrases) VALUES
  ('VISA', '13.7', 'Cancelled Merchandise/Services', '18 April 2026', '1.1.1', 'Reason code {reasonCode} — the merchant''s permitted arguments: {codes}, in register order.', 'How to read this list. Each argument gives the rulebook''s words, then when to nominate it, the evidence that argues it most strongly, and when it does not fit. Nominate an argument whenever the merchant''s records bear on it, even if the evidence is not of the strongest kind, and say how strong it is: your nomination and the strength you give it are what the filing rests on, and a missed argument costs the merchant more than an extra one. Always quote the record you rely on. Reject an argument only when it does not fit this case, or when nothing in the records bears on it. Every argument is listed on every case, but several apply only to one kind of sale or complaint: goods sent back to the merchant, a service cancelled after part of it was used, a reservation held for a later date, a timeshare, a sale made online, by phone or post or away from the merchant''s premises; judge from the records whether this case is that kind. The rule''s words govern the final decision; the lines below are deliberately broader, so that no argument is missed. The merchant''s pack is often one file holding many kinds of record: read all of it. Where a section of the case says an exclusion or limit is MET, rely on it: it was worked out from the record, not read from a document.', 'Terms used below.
INSERT INTO wdp_ai.reason_code (network, code, name, rulebook_edition, catalogue_version, grounds_header, how_to_read, terms_used, supplementary_header, agency_mccs, agency_mccs_reviewed, never_mention, banned_phrases) VALUES
  ('VISA', '12.5', 'Incorrect Amount', '18 April 2026', '1.1.0', 'Reason code {reasonCode} — the merchant''s permitted arguments: {codes}, in register order.', 'How to read this list. Each argument gives the rulebook''s words, then when to nominate it, the evidence that argues it most strongly, and when it does not fit. Nominate an argument whenever the merchant''s records bear on it, even if the evidence is not of the strongest kind, and say how strong it is: your nomination and the strength you give it are what the filing rests on, and a missed argument costs the merchant more than an extra one. Always quote the record you rely on. Reject an argument only when it does not fit this case, or when nothing in the records bears on it. Every argument is listed on every case, but several apply only to one kind of charge or complaint: an amount different from the receipt, a total added up wrongly or with digits swapped, a travel and entertainment charge different from the price quoted, a no-show charge, an advance payment, a charge the merchant may change after the transaction was completed, an adjustment at an ATM; judge from the records whether this case is that kind. The rule''s words govern the final decision; the lines below are deliberately broader, so that no argument is missed. The merchant''s pack is often one file holding many kinds of record: read all of it. Where a section of the case says an exclusion or limit is MET, rely on it: it was worked out from the record, not read from a document.', 'Terms used below.
INSERT INTO wdp_ai.reason_code (network, code, name, rulebook_edition, catalogue_version, grounds_header, how_to_read, terms_used, supplementary_header, agency_mccs, agency_mccs_reviewed, never_mention, banned_phrases) VALUES
  ('VISA', '13.2', 'Cancelled Recurring Transaction', '18 April 2026', '1.0.0', 'Reason code {reasonCode} — the merchant''s permitted arguments: {codes}, in register order.', 'How to read this list. Each argument gives the rulebook''s words, then when to nominate it, the evidence that argues it most strongly, and when it does not fit. Nominate an argument whenever the merchant''s records bear on it, even if the evidence is not of the strongest kind, and say how strong it is: your nomination and the strength you give it are what the filing rests on, and a missed argument costs the merchant more than an extra one. Always quote the record you rely on. Reject an argument only when it does not fit this case, or when nothing in the records bears on it. Every argument is listed on every case, but several apply only to one kind of charge or complaint: a recurring or subscription charge, an installment payment for a single purchase, an unscheduled charge to a card held on file, a payment the cardholder made themselves, a service billed after it was provided, a charge after the account was closed or the cardholder died; judge from the records whether this case is that kind. The rule''s words govern the final decision; the lines below are deliberately broader, so that no argument is missed. The merchant''s pack is often one file holding many kinds of record: read all of it. Where a section of the case says an exclusion or limit is MET, rely on it: it was worked out from the record, not read from a document.', 'Terms used below.
INSERT INTO wdp_ai.reason_code (network, code, name, rulebook_edition, catalogue_version, grounds_header, how_to_read, terms_used, supplementary_header, agency_mccs, agency_mccs_reviewed, never_mention, banned_phrases) VALUES
  ('VISA', '13.3', 'Not as Described or Defective Merchandise/Services', '18 April 2026', '1.0.0', 'Reason code {reasonCode} — the merchant''s permitted arguments: {codes}, in register order.', 'How to read this list. Each argument gives the rulebook''s words, then when to nominate it, the evidence that argues it most strongly, and when it does not fit. Nominate an argument whenever the merchant''s records bear on it, even if the evidence is not of the strongest kind, and say how strong it is: your nomination and the strength you give it are what the filing rests on, and a missed argument costs the merchant more than an extra one. Always quote the record you rely on. Reject an argument only when it does not fit this case, or when nothing in the records bears on it. Every argument is listed on every case, but several apply only to one kind of purchase or complaint: goods or services not as described, damaged or defective; a complaint about quality; goods sent back to the merchant, or that should have been; a service already provided; food from an eating place; a crypto or NFT purchase; a travel agency''s contract with the merchant; a dispute raised after negotiations with the merchant; judge from the records whether this case is that kind. The rule''s words govern the final decision; the lines below are deliberately broader, so that no argument is missed. The merchant''s pack is often one file holding many kinds of record: read all of it. Where a section of the case says an exclusion or limit is MET, rely on it: it was worked out from the record, not read from a document.', 'Terms used below.
