INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('cardholder.attemptedResolutionWithMerchant', 'Did the Cardholder attempt to resolve the dispute with the Merchant, the Merchant''s liquidator, the Ramp Provider, or its Conversion Affiliate as applicable, before the Issuer initiated the Dispute? Answer only from the response recorded against that question. **NOT_FOUND where the form does not ask it or the field is blank — never FALSE.** An answer recorded against a different question is not an answer to this one.', 'truth', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', NULL, 'c65e1404f84', 'The cardholder tried to resolve the dispute with the merchant before the dispute was raised')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('cardholder.expectedReceiptDate', 'What is the last date the cardholder expected to receive the merchandise or services, as stated on the issuer''s questionnaire ("last expected receipt date")? ISO date (YYYY-MM-DD); NOT_FOUND if absent.', 'value', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', 'ISO_DATE', 'c3db60f279a', 'The last date the cardholder expected to receive the goods or services')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('issuer.certifiesCardholderCancelledPriorToExpectedDate', 'Does the issuer''s questionnaire answer "Yes" to whether the cardholder cancelled prior to the expected delivery or receipt date? TRUE for Yes, FALSE for No; NOT_FOUND if the form does not ask it or leaves it blank.', 'truth', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', NULL, 'c09c721199b', 'The issuer certifies the cardholder cancelled before the expected date')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('issuer.certifiesMerchantCancelled', 'Does the issuer''s questionnaire answer "Yes" to whether the merchant cancelled the merchandise or services? TRUE for Yes, FALSE for No; NOT_FOUND if the form does not ask it or leaves it blank.', 'truth', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', NULL, 'ccac6f87347', 'The issuer certifies the merchant cancelled')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('issuer.certifiesMerchantInsolvent', 'Does the issuer''s questionnaire answer "Yes" to whether the merchant is in bankruptcy or liquidation? TRUE for Yes, FALSE for No; NOT_FOUND if the form does not ask it or leaves it blank. This is the issuer''s assertion only, not a public insolvency record.', 'truth', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', NULL, 'c5cd561bc1b', 'The issuer certifies the merchant is in bankruptcy or liquidation')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('issuer.certifiesNonFiatNotDeliveredToWallet', 'Does the issuer''s questionnaire answer "Yes" to whether the non-fiat currency or non-fungible token(s) were not successfully delivered to the destination wallet address supplied by the cardholder at the time of the transaction?', 'truth', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', NULL, 'c6bfbb4d5ee', 'The issuer certifies the currency or token was not delivered to the cardholder''s wallet')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('issuer.firstNotifiedDate', 'What date does the issuer''s questionnaire or certification give as the date the issuer was first notified of the dispute by the cardholder? ISO date (YYYY-MM-DD); the questionnaire writes dates month first (MM/DD/YYYY), as its transaction and processing dates show. NOT_FOUND where the form does not ask it or the field is blank. A date given against a different question — the date the dispute was processed, the purchase date or the date negotiations began — is not an answer to this one.', 'value', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', 'ISO_DATE', 'ca8799d7c93', 'The date the issuer was first notified of the dispute by the cardholder')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('issuer.merchantCancellationDate', 'What date does the issuer''s questionnaire give as the date the merchant cancelled the merchandise or services ("Date merchant cancelled services")? ISO date (YYYY-MM-DD); NOT_FOUND if absent or if the form records no cancellation.', 'value', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', 'ISO_DATE', 'cabae298f53', 'The date the issuer gives for the merchant''s cancellation')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('issuer.negotiationsBeganDate', 'What date does the issuer''s questionnaire or certification give as the date the cardholder began negotiations with the merchant to resolve the dispute? ISO date (YYYY-MM-DD); the questionnaire writes dates month first (MM/DD/YYYY), as its transaction and processing dates show. NOT_FOUND where the form does not ask it or the field is blank; a blank is not a statement that there were no negotiations. A date given against a different question — the purchase date, the date received or the date the issuer was notified — is not an answer to this one.', 'value', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', 'ISO_DATE', 'c37a2fb21d2', 'The date the cardholder began negotiations with the merchant')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('issuer.receivedDate', 'What date does the issuer''s questionnaire give as the date the cardholder — or, for a travel agency paying with a Visa Commercial Card Virtual Account, the Virtual Account holder — received the merchandise or services? ISO date (YYYY-MM-DD); the questionnaire writes dates month first (MM/DD/YYYY), as its transaction and processing dates show. Answer a date of receipt only: an expected, promised or due date is not an answer to this question. NOT_FOUND where the form does not ask it or the field is blank. A date given against a different question — the purchase date, the return date or the cancellation date — is not an answer to this one.', 'value', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', 'ISO_DATE', 'cf2a3b43371', 'The date the cardholder received the merchandise or services')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('issuer.receivedOrExpectedDate', 'What date does the issuer''s questionnaire give as the date the cardholder received, or expected to receive, the merchandise or services? On a merchandise form the field is "Date the cardholder received or expected to receive the merchandise"; on a services form it is "Date of service or expected service". ISO date (YYYY-MM-DD); the questionnaire writes dates month first (MM/DD/YYYY), as its transaction and processing dates show. Where the form gives a received date and a different expected date, answer UNRESOLVED and keep both in the quote. NOT_FOUND where the form does not ask it or the field is blank. A date given against a different question — the transaction date, the cancellation date, the contract date or the date of an attempted return — is not an answer to this one.', 'value', 'DOCUMENT', 'issuerDisputeQuestionnaire', 'ISSUER', 'ISO_DATE', 'c90223444a1', 'The date the cardholder received or expected to receive the merchandise or services')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('bonding.letterOrAdviceDate', 'What date is shown on the letter or advice from the bonding authority or insurance scheme about this claim? ISO date (YYYY-MM-DD); NOT_FOUND if absent.', 'value', 'DOCUMENT', 'bondingSchemeRecord', 'ISSUER', NULL, 'c8bd77b0414', 'The date of the letter or advice from the bonding or insurance scheme')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('bonding.reimbursementClaimSubmitted', 'Does the document show that the Cardholder, the traveler, or the Issuer on their behalf submitted a reimbursement claim or request to the bonding authority or insurance scheme for the disputed travel services? TRUE where a claim, request or the scheme''s acknowledgment of one is shown; FALSE where the document states no claim was made; NOT_FOUND where the document does not say.', 'truth', 'DOCUMENT', 'bondingSchemeRecord', 'ISSUER', NULL, 'cb6858a0d5e', 'A reimbursement claim was submitted to the bonding or insurance scheme')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('bonding.reimbursementClaimSubmittedDate', 'What date does the document show the reimbursement claim or request was submitted to the bonding authority or insurance scheme? ISO date (YYYY-MM-DD); NOT_FOUND if absent.', 'value', 'DOCUMENT', 'bondingSchemeRecord', 'ISSUER', NULL, 'c477b10950d', 'The date the reimbursement claim was submitted to the scheme')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('bonding.schemeInsufficient', 'Do the documents show that the bond or insurance scheme is insufficient to reimburse the claimed travel-services loss? Read the scheme''s own letter or advice as well as the issuer''s statement of the advice it was given: express advice that no funds or no bond is available, that limits are exhausted, or that the loss will not be covered means insufficient — TRUE. FALSE where the scheme says it will pay or has paid. NOT_FOUND where no document addresses sufficiency: a pending claim, an acknowledgment or an absence of response is not insufficiency.', 'truth', 'DOCUMENT', 'bondingSchemeRecord', 'ISSUER', NULL, 'c0263314ce2', 'The bond or insurance scheme is shown insufficient to cover the loss')
INSERT INTO wdp_ai.fact_key (key, question, type, origin, source_ref, source_side, value_domain, contract_version, label) VALUES
  ('travel.servicesCoveredByBondingOrInsuranceScheme', 'Does the document show that the disputed travel services were covered by a bonding authority or insurance scheme — insolvency protection for the booking, for example ATOL, ABTA or a travel-industry bond? The cardholder''s own travel insurance is not such a scheme. TRUE where the document states the cover or is the scheme''s own correspondence about this booking; FALSE where it states the services were not covered; NOT_FOUND where the document does not address cover.', 'truth', 'DOCUMENT', 'bondingSchemeRecord', 'ISSUER', NULL, 'cff777865bc', 'The services were covered by a bonding authority or insurance scheme')
