INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G18', 'PRECONDITION', 'VISA-13.1-11.10.2.3', 'The Cash-Back portion of a Visa Cash-Back Transaction', 'ID', 'IDRC25', false, 'RECORD', 'cash-back portion of the transaction', 'the transaction-record section shows this exclusion as MET. Rely on the result shown there; never work it out yourself.', 'the record entry the section names, cited by its bracketed field name.', 'the section shows it as NOT MET.', 31, 'ALL', 'CASH_BACK_PORTION')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G19', 'PRECONDITION', 'VISA-13.1-11.10.2.3', 'An Automated Fuel Dispenser Transaction', 'ID', 'IDRC25', false, 'RECORD', 'automated fuel dispenser transaction', 'the transaction-record section shows this exclusion as MET. Rely on the result shown there; never work it out yourself.', 'the record entry the section names, cited by its bracketed field name.', 'the section shows it as NOT MET.', 30, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G13', 'PRECONDITION', 'VISA-13.1-11.10.2.3', 'A Transaction in which the Cardholder cancelled the merchandise or service before the expected
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G14', 'PRECONDITION', 'VISA-13.1-11.10.2.3', 'A Transaction in which merchandise is being held by the Cardholder''s country''s customs agency', 'ID', 'IDRC5', false, 'JUDGEMENT', 'merchandise held by customs in the cardholder''s country', 'a carrier or tracking record shows the goods held by customs, or awaiting customs clearance or duties, in the country they were being delivered to.', 'the carrier''s tracking record showing the goods held at customs in the destination country, with the destination address.', 'the goods are held in the merchant''s own country or elsewhere in transit, which does not help the merchant; or they have since been released and delivered.', 11, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G15', 'PRECONDITION', 'VISA-13.1-11.10.2.3', 'A Transaction that the Cardholder states is fraudulent', 'ID', 'IDRC25', false, 'JUDGEMENT', 'cardholder states the transaction is fraudulent, a different reason code', 'the issuer''s filing or the cardholder''s own words say the cardholder did not make or authorise the payment, or call it fraud or unauthorised use of their card — so the dispute belongs under a fraud reason code, not this one.', 'the words in the dispute filing saying the cardholder did not make or authorise the transaction.', 'the cardholder acknowledges making the purchase and disputes what was received or whether it was received, even if they say the merchant was not who they thought; or only the merchant alleges fraud by the cardholder, which is an other argument.', 12, 'ALL', 'FRAUD_CLAIM')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G16', 'PRECONDITION', 'VISA-13.1-11.10.2.3', 'A Dispute regarding the quality of merchandise or service provided', 'ID', 'IDRC25', false, 'JUDGEMENT', 'dispute about quality, a different reason code', 'the issuer''s filing or the cardholder''s own words show the goods or service were received, and the complaint is that they were faulty, damaged, not as described, misrepresented or unsatisfactory — so the dispute belongs under a quality or not-as-described reason code, not this one.', 'the cardholder''s or issuer''s words describing a problem with what was received.', 'the complaint is that nothing, or only part, was received, including an item missing or substituted inside the delivery; or only the merchant describes a quality issue.', 13, 'ALL', NULL)
