  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G27', 'PRECONDITION', 'VISA-13.1-11.10.2.4', 'If the Cardholder or traveler, or the Issuer on behalf of the Cardholder or traveler was required to attempt to obtain reimbursement from a bonding authority/insurance scheme, wait 60 calendar days from the date the claim was submitted to the bonding authority/insurance scheme before initiating a Dispute1,6,7', 'ID', 'IDRC25', false, 'TIME_LIMIT', 'raised within the waiting period counted from the reimbursement claim', 'the time-limits section shows this limit as MET. Rely on the figures shown there; never count days yourself.', 'the system''s day count, cited by its bracketed field name.', 'the time-limits section shows it as NOT MET or NOT YET KNOWN.', 27, 'EUROPE', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G30', 'PRECONDITION', 'VISA-13.1-11.10.2.2', 'For a Dispute related to non-receipt of travel services from a provider that is insolvent or bankrupt, if the services are covered by a bonding authority/insurance scheme, the Cardholder or traveler, or the Issuer on behalf of the Cardholder or traveler must attempt to obtain reimbursement from the relevant bonding authority/insurance scheme, unless the bond or insurance scheme is insufficient. If the bond or insurance scheme is insufficient, the Issuer may use information in the public domain to initiate the Dispute.', 'ID', 'IDRC25', false, 'JUDGEMENT', 'no attempt to claim from the bonding or insurance scheme', 'the records show the dispute is for travel services not received from a provider that is insolvent or bankrupt, that the services were covered by a bonding authority or insurance scheme — insolvency protection for the booking, for example ATOL, ABTA or a travel-industry bond, never the cardholder''s own travel insurance — and that neither the cardholder, the traveler nor the issuer on their behalf attempted to obtain reimbursement from that scheme before the dispute was raised. Both the insolvency and the scheme cover must be shown in the records; never nominate this because the records are silent about a claim.', 'the issuer''s form or the scheme''s own letter recording the provider''s insolvency and the scheme cover, with no claim, reimbursement request or acknowledgment from the scheme anywhere in the records.', 'the records show a claim or reimbursement request was made to the scheme by the cardholder, the traveler or the issuer; the records show the scheme was insufficient — no funds or no bond available, limits exhausted, the loss not covered — so the issuer may file on public-domain information; the provider is not shown insolvent or bankrupt; the services are not shown covered by a scheme; or the dispute is not about travel services.', 17, 'EUROPE', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G1', 'GROUND', 'VISA-13.1-11.10.2.6', 'A credit or Reversal issued by the Merchant was not addressed by the Issuer in the Dispute', 'CP', NULL, false, NULL, 'a credit or reversal was already issued', 'the merchant''s records show a refund, credit or reversal of this purchase — a payment-system line, a refund confirmation, a reversal record or a statement of refunds to the card — with its date and amount, and the record itself shows it as a refund, credit or reversal of the disputed transaction. A withdrawal, payout or transfer of the cardholder''s own balance, winnings or sale proceeds back to the card is not a refund of this purchase and is not this argument.', 'the merchant''s payment-system record of the refund, credit or reversal of this purchase, showing its date, its amount, the card it went to and that it reverses or refunds the disputed transaction.', 'only an offer or promise to refund; a refund to a different card, a voucher or store credit; a value shown on a cancelled, rejected or pending return; a withdrawal, payout or transfer of the cardholder''s own balance, winnings or sale proceeds back to the card, which is not a refund of this purchase; or no record of any refund, credit or reversal of this purchase.', 1, 'ALL', 'CREDIT')
