  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G5', 'GROUND', 'VISA-13.1-11.10.2.6', 'For merchandise that was delivered, proof of delivery that contains the full delivery address
(tracking with partial address is not permitted)', 'NL', NULL, false, NULL, 'proof of delivery', 'a carrier''s or the merchant''s own delivery record shows the goods delivered — including one reproduced as a screenshot or exhibit inside a letter — even where that record shows only part of the address or none, provided the merchant''s order or despatch record for the same order gives the delivery address. A signature, delivery photo or located delivery on the record is part of it.', 'a delivery record marked delivered that itself shows the full delivery address, matching the address agreed for the order, with a signature or photo.', 'nothing shows the goods delivered — only a despatch note, "shipped", "out for delivery", "attempted" or "returned to sender"; the records show delivery to an address other than the agreed one; or the only support is a letter or email saying the goods arrived, with no delivery record behind it.', 4, 'ALL', NULL)
