  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1'), 'G10', 'GROUND', 'VISA-13.1-11.10.2.6', 'For Transactions involving the acquisition of non-fiat currency (for example: cryptocurrency) or
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G1', 'GROUND', 'VISA-13.7-11.10.8.6', 'A credit or Reversal issued by the Merchant was not addressed by the Issuer in the Dispute', 'CP', NULL, false, NULL, 'a credit or reversal already issued and not addressed in the dispute', 'the merchant''s records show a refund, credit or reversal of this purchase, in whole or in part — a payment-system line, a refund confirmation, a reversal record or a statement of refunds to the card — with its date and amount, and the record itself shows it refunds or reverses the disputed transaction.', 'the merchant''s payment-system record of the refund, credit or reversal of this purchase, showing its date, its amount, the card it went to and that it refunds or reverses the disputed transaction, beside an issuer''s filing that disputes the amount without deducting it.', 'only an offer or promise to refund; a refund to a different card, a voucher or store credit; a refund shown as pending, cancelled or rejected; a refund of a different purchase; the issuer''s filing already mentions the refund, credit or reversal, or the amount disputed is already reduced by it; or no record of any refund, credit or reversal of this purchase; or the refund is already deducted and the issuer disputes more than the unused part or the returned goods, which is the amount argument.', 1, 'ALL', 'CREDIT')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G2', 'GROUND', 'VISA-13.7-11.10.8.6', 'The Cardholder no longer disputes the Transaction', 'CNLD', NULL, false, NULL, 'the cardholder no longer disputes the transaction', 'the merchant''s records hold the cardholder''s own written words saying the matter is resolved; that they accept a rebooking, a new date, a replacement or a refund already given and are content; or that they are withdrawing the dispute.', 'a message from the cardholder, dated after the dispute was raised, saying in terms that they no longer dispute the charge.', 'the only records are the merchant''s own notes, call logs or summaries; a refund or credit record on its own, which is the credit argument; the cardholder''s words were written before the dispute was raised; or the cardholder accepts something but still asks for their money back.', 2, 'ALL', 'CARDHOLDER_WITHDREW')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G3', 'GROUND', 'VISA-13.7-11.10.8.6', 'The Transaction Receipt, as specified in Section 5.9.2.2, Required Transaction Receipt Content for All Transactions or other record to prove that the Merchant properly disclosed a limited return or cancellation policy at the time of the Transaction, as specified in Section 5.4.2.5, Disclosure to Cardholders of Return, Refund, and Cancellation Policies', 'NL', NULL, false, NULL, 'a limited cancellation or return policy was properly disclosed at the time of purchase', 'the merchant''s records show a limited return, refund or cancellation policy — for example non-refundable, a cancellation deadline or fee, or store credit only — put before the cardholder when they bought: on the checkout pages with a box to tick or a button to accept, on the receipt or contract with a place for the cardholder to accept it, at the till before payment, or by email, letter or text for a phone or mail order.', 'the receipt, checkout record or contract for this purchase showing the policy and the cardholder''s acceptance at the time of purchase — the ticked box or accept button, or the acceptance space on the receipt — and, for a reservation, the confirmation stating the cancellation deadline and the charge for missing it.', 'the policy was shown only after the purchase; it was not in the form the channel needs, such as an online sale with nothing for the cardholder to tick or click, or a receipt or contract with no place to accept it; the policy did not limit returns or cancellations; the cardholder cancelled or returned within the policy; a timeshare cancelled within 14 days of the contract or of receiving the contract documents, or charged under the wrong merchant category code; a reservation the cardholder tried to cancel within 24 hours of receiving its confirmation; or, in Europe, a sale made away from the merchant''s premises or at a distance and cancelled within 14 days, unless the contract is of a kind the 14-day period does not cover, which is the Europe exceptions argument.', 4, 'ALL', 'POLICY')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G4', 'GROUND', 'VISA-13.7-11.10.8.6', 'To demonstrate that the Cardholder received the Merchant’s cancellation or return policy and did not cancel according to the disclosed policy', 'NL', NULL, false, NULL, 'the cardholder received the cancellation terms and did not cancel according to them', 'the merchant''s records show the cardholder was given the merchant''s cancellation or return terms for this purchase, or the issuer''s form says a cancellation or return policy was provided, and that the cardholder cancelled or returned outside those terms: after the deadline they set, by a route they did not allow, without returning what they required, or not at all. The terms may have been given, for example, by acceptance at checkout, on a signed receipt or contract, or in a booking confirmation.', 'the terms as the cardholder received or accepted them for this purchase, with the date, or the issuer''s form stating that a policy was provided, together with the cardholder''s cancellation or return request showing when and how it was made.', 'neither the merchant''s records nor the issuer''s form show the cardholder received the terms; the cancellation or return was within the terms; a timeshare cancelled within 14 days of the contract or of receiving the contract documents, or charged under the wrong merchant category code; a reservation the cardholder tried to cancel within 24 hours of receiving its confirmation; a No-Show charge for more than one day''s accommodation or rental, as to the charge beyond one day; or, in Europe, a sale made away from the merchant''s premises or at a distance and cancelled within 14 days, unless the contract is of a kind the 14-day period does not cover, which is the Europe exceptions argument.', 3, 'ALL', 'POLICY')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G6', 'PRECONDITION', 'VISA-13.7-11.10.8.3', 'A Straight Through Processing Transaction', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G7', 'PRECONDITION', 'VISA-13.7-11.10.8.3', 'A Dispute regarding the quality of the service rendered or the quality of merchandise, unless a Credit Transaction Receipt, as specified in Section 5.9.2.2, Required Transaction Receipt Content for All Transactions is provided', 'ID', 'IDRC25', false, 'JUDGEMENT', 'dispute about quality, a different reason code', 'the issuer''s filing or the cardholder''s own words show the complaint itself is about the quality of goods received or a service rendered — faulty, damaged, poor or unsatisfactory — and the issuer''s documents in the case include no credit receipt from the merchant.', 'the cardholder''s or issuer''s words describing what was wrong with what was received or rendered, with the issuer''s documents showing no credit receipt among them.', 'the complaint is that a cancellation or return was not refunded, even where poor quality is given as the reason for cancelling or returning; the complaint is only that a cancellation or return was not refunded, with nothing said about what was received; the issuer has provided a credit receipt from the merchant; the issuer''s documents are not in the case; or only the merchant describes a quality problem.', 6, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G8', 'PRECONDITION', 'VISA-13.7-11.10.8.3', 'A Dispute regarding Value-Added Tax (VAT), unless a Credit Transaction Receipt, as specified in Section 5.9.2.2, Required Transaction Receipt Content for All Transactions is provided', 'ID', 'IDRC25', false, 'JUDGEMENT', 'dispute about value-added tax', 'the issuer''s filing or the cardholder''s own words show the dispute is about VAT — the tax charged, the tax not refunded, or a refund made net of tax — and the issuer''s documents in the case include no credit receipt from the merchant.', 'the words in the dispute filing naming VAT as what is disputed, with the receipt or refund record showing the tax figure the dispute concerns, and no credit receipt among the issuer''s documents.', 'VAT is mentioned only as part of the total price disputed; the issuer has provided a credit receipt from the merchant; the issuer''s documents are not in the case; or only the merchant mentions VAT.', 7, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G9', 'PRECONDITION', 'VISA-13.7-11.10.8.3', 'A Transaction in which returned merchandise is held by a customs agency other than the Merchant’s country’s customs agency1', 'ID', 'IDRC25', false, 'JUDGEMENT', 'returned goods held by customs outside the merchant''s country', 'a carrier, tracking or customs record shows the goods the cardholder sent back to the merchant held by a customs agency, or awaiting customs clearance or duties, in a country other than the merchant''s, at or after the time the dispute was raised.', 'the return shipment''s tracking or customs record, dated on or after the day the dispute was raised, showing the hold and the country holding it, with the merchant''s address showing its own country.', 'the goods are held by the merchant''s own country''s customs; the hold is on the delivery to the cardholder, not the return; the goods have since been released, delivered or received back by the merchant; or, in Europe, the sale was made away from the merchant''s premises or at a distance.', 8, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G11', 'PRECONDITION', 'VISA-13.7-11.10.8.3', 'A Transaction that the Cardholder states is fraudulent', 'ID', 'IDRC25', false, 'JUDGEMENT', 'cardholder states the transaction is fraudulent, a different reason code', 'the issuer''s filing or the cardholder''s own words say the cardholder did not make, take part in or agree to the purchase at all, or call it fraud or the use of their card by someone else — so the dispute belongs under a fraud reason code, not this one.', 'the words in the dispute filing saying the cardholder did not make or take part in the transaction.', 'the cardholder acknowledges making the purchase or booking and says only that a charge after their cancellation was not authorised or should not have been taken, which is the cancellation complaint itself; or only the merchant alleges fraud by the cardholder.', 5, 'ALL', 'FRAUD_CLAIM')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G15', 'PRECONDITION', 'VISA-13.7-11.10.8.1', 'The Cardholder cancelled or returned merchandise, cancelled services, cancelled a timeshare Transaction, or cancelled a Guaranteed Reservation.', 'ID', 'IDRC25', false, 'JUDGEMENT', 'the cardholder did not cancel or return the purchase', 'the issuer''s filing or the cardholder''s own words describe a complaint other than a cancellation or a return — for example that the goods never arrived, that the service was poor, or that they do not recognise the charge — or the merchant''s complete contact history for this order shows no cancellation or return request at all.', 'the issuer''s filing, quoted, showing the complaint is something other than a cancellation or return; or the merchant''s complete contact history for this order showing no cancellation or return request.', 'the cardholder asked to cancel or return by any route, even late or by a route the terms did not allow, which is the cancellation-terms argument; the cardholder tried to cancel a reservation within 24 hours of receiving its confirmation; a reservation simply not used, where the No-Show charge covers more than one day; or the records say nothing about whether the cardholder cancelled; the service was used after the date given as the cancellation, which is the amount argument where part was used, or the full-use argument where all of it was. A complaint about quality may also be the quality argument, and an unrecognised charge the fraud argument.', 10, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G16', 'PRECONDITION', 'VISA-13.7-11.10.8.2', 'If the merchandise was shipped before the Transaction was cancelled, the Cardholder must return the merchandise, if received.', 'ID', 'IDRC25', false, 'JUDGEMENT', 'goods delivered before the cancellation and not returned', 'the records show the merchandise was shipped before the cardholder cancelled and reached the cardholder, and either the cardholder''s own words or the issuer''s filing say the goods were kept, or the merchant''s returns records for this order show no return received.', 'the shipping record dated before the cancellation and the carrier''s proof of delivery to the cardholder, with the merchant''s returns record for this order showing nothing received, or the cardholder''s own words that they still have the goods.', 'the goods were shipped only after the cardholder cancelled; they never reached the cardholder; the cardholder sent them back, or tried to and the merchant refused the return or told them not to send it; the goods were sent back and are held by customs, which may be the customs argument; part was sent back and part kept, which is the amount argument for the part kept; the records say nothing about a return; or the purchase was a service.', 9, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G17', 'PRECONDITION', 'VISA-13.7-11.10.8.2', 'The Dispute amount is limited to either: The value of the unused portion of the cancelled service; The value of the returned merchandise', 'ID', 'IDRC25', true, 'JUDGEMENT', 'the dispute claims more than the unused part of the service or the returned goods', 'the records show the cardholder used part of the service, not all of it — nights stayed, sessions attended, days of access, including use after the date given as the cancellation — or kept part of the merchandise and sent the rest back, and the dispute claims the full transaction amount or otherwise appears to include the part that was used or kept.', 'the merchant''s usage, stay, access or delivery records for this purchase showing what was used or kept, with the dates, beside the amount the issuer disputes.', 'nothing was used or kept; all of it was used, kept or available for the whole period paid for, which is the full-use argument; the dispute is plainly limited to what was unused or returned; a refund the issuer has not deducted, which is the credit argument; or the records do not show what was used or kept.', 12, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G18', 'PRECONDITION', 'VISA-13.7-11.10.8.2', 'Before the Issuer may initiate a Dispute, the Cardholder must attempt to resolve the dispute with the Merchant or the Merchant’s liquidator.', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G24', 'PRECONDITION', 'VISA-13.7-11.10.8.5', 'A detailed description of the merchandise or services purchased. This description must contain additional information beyond the data required in the Clearing Record (for example: the MCC of the Merchant is 5651 – Family Clothing Stores, and the description states a pair of blue jeans).1', 'ID', 'IDRC25', true, 'JUDGEMENT', 'insufficient description of the purchase', 'the issuer''s description of what was bought says no more than the payment record already shows — only the merchant''s name, the amount, a date, or a general word such as goods, services, booking or cancelled — or describes something other than what the merchant sold.', 'the issuer''s description, quoted, showing it names nothing specific about the purchase, or names something the merchant did not sell.', 'the description names what was bought — the item, service or booking — in more detail than the payment record carries; or the payment record itself carries item-level detail of the purchase.', 13, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G25', 'PRECONDITION', 'VISA-13.7-11.10.8.2', 'The Dispute amount is limited to either: The value of the unused portion of the cancelled service; The value of the returned merchandise', 'ID', 'IDRC25', false, 'JUDGEMENT', 'the cardholder used or kept all of what the charge paid for', 'the records show the cardholder used all of the service this charge paid for — for example the stay, the sessions, a deposit credited and played or withdrawn, digital items delivered and used, or the use a charge billed in arrears paid for — or that the service stayed available to them for the whole period the charge paid for, the cancellation taking effect only at its end; or that they kept all of the merchandise and sent none back.', 'the merchant''s usage, access, account or delivery records for this purchase showing that use or availability, with the dates, tied to what this charge paid for. Records of use of the account in general, not tied to this charge, are PARTIAL at most.', 'part of the service was unused or part of the goods sent back, which is the amount argument; the cancellation took effect before the period this charge paid for began; the records do not show what was used, kept or available; or, in Europe, a sale made at a distance or away from the merchant''s premises and cancelled within 14 days, unless the contract is of a kind the 14-day period does not cover.', 11, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G13', 'PRECONDITION', 'VISA-13.7-11.10.8.4', 'Before initiating a Dispute, an Issuer must wait 15 calendar days1 from the date the merchandise was returned, merchandise was canceled, or services were canceled.', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G14', 'PRECONDITION', 'VISA-13.7-11.10.8.4', 'A Dispute must be processed no later than 120 calendar days from one of the following: – The Transaction Processing Date', 'ID', 'IDRC25', false, 'TIME_LIMIT', 'raised beyond the time limit counted from the processing date', 'the time-limits section shows this limit as MET. Rely on the figures shown there; never count days yourself.', 'the system''s day count, cited by its bracketed field name.', 'the time-limits section shows it as NOT MET or NOT YET KNOWN.', 15, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G20', 'PRECONDITION', 'VISA-13.7-11.10.8.4', 'A Dispute must be processed no later than 120 calendar days from one of the following: – The date the Cardholder received or expected to receive the merchandise or services, not to exceed 540 calendar days from the Transaction Processing Date', 'ID', 'IDRC25', false, 'TIME_LIMIT', 'raised beyond the time limit counted from the date the purchase was received or expected', 'the time-limits section shows this limit as MET. Rely on the figures shown there; never count days yourself.', 'the system''s day count, cited by its bracketed field name.', 'the time-limits section shows it as NOT MET or NOT YET KNOWN.', 16, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G21', 'PRECONDITION', 'VISA-13.7-11.10.8.4', 'A Dispute must be processed no later than 120 calendar days from one of the following: – The date the Cardholder received or expected to receive the merchandise or services, not to exceed 540 calendar days from the Transaction Processing Date', 'ID', 'IDRC25', false, 'TIME_LIMIT', 'raised beyond the latest time limit the 540-day cap allows', 'the time-limits section shows this limit as MET. Rely on the figures shown there; never count days yourself.', 'the system''s day count, cited by its bracketed field name.', 'the time-limits section shows it as NOT MET or NOT YET KNOWN.', 17, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G19', 'PRECONDITION', 'VISA-13.7-11.10.8.2-EUROPE', 'The cancellation period for off-premises, distance selling does not apply to contracts for goods or services where any of the following apply: Price is dependent on fluctuations in the financial market. Made to measure goods are supplied. Goods are liable to deteriorate or expire rapidly. Sealed goods, subject to health and safety provisions, are supplied. Goods are not received in physical form (software download). The Transaction is a T&E Transaction. The Merchant Outlet is based in Israel, Switzerland, or Türkiye.', 'ID', 'IDRC25', true, 'JUDGEMENT', 'the 14-day cancellation period for distance and off-premises sales does not apply to this contract', 'the sale was made online, by phone or mail, or away from the merchant''s premises, and the records show the contract is of a kind the 14-day cancellation period excludes: a price that depends on movements in the financial market; goods made to measure; goods that deteriorate or expire rapidly; sealed goods supplied under health and safety rules; goods not received in physical form, such as a software download; a travel and entertainment purchase, meaning a purchase from an airline, a cruise line, a hotel or other lodging merchant, a travel agency or a vehicle rental merchant; or a merchant outlet based in Israel, Switzerland or Türkiye.', 'the order, booking or product record for this purchase showing what was bought and how the sale was made — for example a made-to-order item, a download, or a hotel, flight, cruise or car rental booking.', 'the sale was made face to face at the merchant''s premises; the contract is not of an excluded kind; or the records do not show what was bought; or the issuer''s filing does not rely on the 14-day cancellation period.', 14, 'EUROPE', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G23', 'PRECONDITION', 'VISA-13.7-11.10.8.5-EUROPE', 'Certification of the following, as applicable:', 'ID', 'IDRC25', true, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G5', 'PRECONDITION', 'VISA-13.7-11.10.8.3', 'An ATM Cash Disbursement', 'ID', 'IDRC25', false, 'RECORD', 'ATM cash disbursement', 'the transaction-record section shows this exclusion as MET. Rely on the result shown there; never work it out yourself.', 'the record entry the section names, cited by its bracketed field name.', 'the section shows it as NOT MET.', 18, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G10', 'PRECONDITION', 'VISA-13.7-11.10.8.3', 'The Cash-Back portion of a Visa Cash-Back Transaction', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G12', 'PRECONDITION', 'VISA-13.7-11.10.8.3', 'An Automated Fuel Dispenser Transaction', 'ID', 'IDRC25', false, 'RECORD', 'automated fuel dispenser transaction', 'the transaction-record section shows this exclusion as MET. Rely on the result shown there; never work it out yourself.', 'the record entry the section names, cited by its bracketed field name.', 'the section shows it as NOT MET.', 19, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7'), 'G22', 'PRECONDITION', 'VISA-13.7-11.10.8.5', 'Certification of the following, as applicable:', 'ID', 'IDRC25', true, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G1', 'GROUND', 'VISA-12.5-11.9.4.6', 'A credit or Reversal issued by the Acquirer was not addressed by the Issuer in the Dispute', 'CP', NULL, false, NULL, 'a credit or reversal already issued and not addressed in the dispute', 'the merchant''s records show a refund, credit, reversal or correction of the disputed charge processed back to the card, in whole or in part — for example a refund of the overcharge, a reversal of the charge, or the charge reversed and processed again at a lower amount — with its date and amount, and the record itself shows it refunds, reverses or corrects this charge rather than another purchase on the same card.', 'the payment-system record of the refund, credit, reversal or correction of this charge, showing its date, its amount, the card it went to and that it relates to the disputed charge, beside an issuer''s filing that disputes the amount without deducting it.', 'only an offer or promise to refund; a refund to a different card, a voucher or store credit; a refund shown as pending, cancelled or rejected; a refund of a different purchase on the same card; the issuer''s filing already mentions the refund, credit or reversal, or the amount disputed is already reduced by it; no record of any refund, credit, reversal or correction of this charge; or the refund is already deducted and the issuer disputes more than the difference between the amounts, which is the difference argument.', 1, 'ALL', 'CREDIT')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G13', 'GROUND', 'VISA-12.5-11.9.4.6', 'The Cardholder no longer disputes the Transaction', 'CNLD', NULL, false, NULL, 'the cardholder no longer disputes the transaction', 'the merchant''s records hold the cardholder''s own written words saying the matter is resolved; that they accept the amount charged — for example that they had forgotten a tip, an extra or an item they ordered; or that they are withdrawing the dispute.', 'a message from the cardholder, dated after the dispute was raised, saying in terms that they no longer dispute the charge or accept the amount charged.', 'the only records are the merchant''s own notes, call logs or summaries; a refund or credit record on its own, which is the credit argument; the cardholder''s words were written before the dispute was raised; the cardholder accepts the amount but still asks for money back; or the cardholder accepts part of the charge and still disputes the rest, which may bear on the difference argument.', 2, 'ALL', 'CARDHOLDER_WITHDREW')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G14', 'GROUND', 'VISA-12.5-11.9.4.6', 'Transaction Receipt, as specified in Section 5.9.2.2, Required Transaction Receipt Content for All Transactions or other record to prove that the Transaction amount was correct', 'NL', NULL, false, NULL, 'the receipt shows the amount charged was correct', 'the merchant''s records hold a receipt or other record of this transaction — for example a till or terminal receipt, a signed bill, an invoice, an order confirmation or a checkout page — showing a total equal to the amount processed shown in the transaction record, including a receipt whose handwritten total, such as a tip written in by the cardholder, equals the amount processed even where the printed amount is lower.', 'the receipt for this transaction, naming the merchant, the date and a total equal to the amount processed, signed, PIN-verified or otherwise accepted by the cardholder — or, for a sale made online or by phone, the order or checkout record showing the total the cardholder accepted — and, where the filing says the total was added up wrongly, an itemised record whose items the cardholder accepted.', 'the receipt or record shows a total different from the amount processed; the receipt''s handwritten total differs from the amount processed, because the handwritten amount is the one that counts, even where the printed amount matches; the total matches only in a different currency, which belongs under the incorrect-currency reason code; the amount processed includes charges added after the receipt was given, such as charges added after check-out or the end of a rental, which may be the after-completion argument; the merchant''s own records say the amount charged was wrong, that it refunded the difference or that it accepts the dispute, which may be the credit argument where a refund is recorded; the only record is a payment-system entry — a capture, authorisation or settlement record — which shows what was charged, not what was sold; or the only support is the merchant''s own statement that the amount was correct, with no receipt or record behind it.', 3, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G5', 'PRECONDITION', 'VISA-12.5-11.9.4.3', 'A T&E Transaction in which there is a difference between the quoted price and the actual charges made by the Merchant', 'ID', 'IDRC25', false, 'JUDGEMENT', 'travel and entertainment charge different from the price quoted', 'the merchant is an airline, a cruise line, a hotel or other lodging merchant, a travel agency, a vehicle rental merchant or, in the United States, a passenger railway, and the issuer''s filing or the cardholder''s own words show the complaint is that the amount charged differs from the price, rate or estimate the merchant gave — for example a final hotel bill with extras above the booked rate, or a car rental bill above the rental quote.', 'the booking, rental agreement or quote the cardholder received for this purchase, showing the price quoted, with the merchant''s final bill or folio for this transaction showing the charges actually made.', 'the merchant is of another kind — for example a restaurant, a shop, or an event or attraction ticket seller; no price, rate or estimate was given before or when the service began; the amount charged is the price quoted; the merchant''s own bill or folio equals the price quoted and only the amount processed differs from it — a processing error, not a difference between the quote and the charges made — which may be the credit argument where a refund was made; or only the merchant describes the complaint. Charges added after check-out or the end of a rental may also be the after-completion argument, and both may be nominated; a charge for a reservation the cardholder did not use is the no-show argument.', 4, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G6', 'PRECONDITION', 'VISA-12.5-11.9.4.3', 'A No-Show Transaction', 'ID', 'IDRC25', false, 'JUDGEMENT', 'no-show charge for an unclaimed reservation', 'the merchant''s records show the disputed charge was made because the cardholder neither cancelled nor claimed a reservation held with their card — for example a hotel room, a rental vehicle or another booking charged as a no-show — including where the cardholder says they cancelled but the merchant''s records show no cancellation.', 'the reservation confirmation for this booking, with the merchant''s record that the reservation was held and not claimed and that the charge was processed as a no-show, such as a folio or receipt marked no-show.', 'the charge is for a stay, rental or service the cardholder used; the charge is a deposit or payment in advance taken when booking, which may be the advance-payment argument; the records do not show a reservation held for the cardholder; or the records show the cardholder cancelled the reservation under its terms, which is a cancellation complaint for a cancellation reason code.', 5, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G7', 'PRECONDITION', 'VISA-12.5-11.9.4.3', 'An Advance Payment1', 'ID', 'IDRC25', false, 'JUDGEMENT', 'advance payment for goods or services to be provided later', 'the merchant''s records mark the disputed charge as a deposit, advance payment or prepayment — for part or all of the price — for goods or services to be provided at a later date, for example a deposit on an order or a stay or booking the receipt calls a prepayment.', 'the advance-payment agreement the cardholder accepted before paying, showing the description, the total price and the cancellation terms with their deadline, with the receipt for this charge marked as an advance payment or prepayment and giving the start or delivery date.', 'a ticket, booking, service or subscription paid at purchase whose records do not call it a deposit, advance payment or prepayment — its amount, if disputed, is the receipt argument; the goods or services were provided when the charge was made; the full price was taken in advance by a merchant other than a travel and entertainment merchant, a seller of custom-made goods or services, a seller in person of goods to be supplied later, or a provider of recreation related to travel and tourism; or the issuer''s filing or the cardholder''s own words say no terms were given before paying and the merchant''s records show none. A no-show charge for an unused reservation is the no-show argument.', 6, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G8', 'PRECONDITION', 'VISA-12.5-11.9.4.3', 'A Transaction for which the Merchant has the right to alter the Transaction amount without the Cardholder’s consent after the Transaction was completed', 'ID', 'IDRC25', false, 'JUDGEMENT', 'amended amount or delayed charge the merchant may process after the transaction', 'the merchant rents vehicles, boats, aircraft, motorcycles, bicycles, motor homes, equipment or clothing, or runs a hotel or other lodging, a campground or a cruise, and the disputed amount, or the part of it the cardholder complains of, was added or changed after check-out, return or disembarkation — an amended amount, or a delayed charge such as fuel, mileage, tolls, parking or traffic fines, minibar or damage — for the rental, stay or cruise the cardholder took part in. This includes charges that a later bill or folio from the merchant carries and an earlier bill or folio given to the cardholder — for example one the issuer attached — does not, where the disputed amount is those charges.', 'the rental agreement, registration card or booking the cardholder accepted for this rental, stay or cruise, with the amended receipt or the merchant''s explanation of the delayed charge sent to the cardholder and, for damage, the damage documentation the merchant gave the cardholder — or the earlier and later bills or folios side by side, showing the charges added after the earlier one was given.', 'the merchant is of another kind, such as a restaurant or a shop; the charge was agreed by the cardholder at the time rather than added afterwards; the charge has no connection with the rental, stay or cruise; or, for a damage charge, the records show the cardholder sent an alternative repair estimate and no agreement on the cost was reached, which the cardholder may dispute. A difference from a price quoted at booking may also be the quoted-price argument, and both may be nominated.', 7, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G11', 'PRECONDITION', 'VISA-12.5-11.9.4.5', 'A copy of the Transaction Receipt, as specified in Section 5.9.2.2, Required Transaction Receipt Content for All Transactions or other record with the correct Transaction Amount', 'ID', 'IDRC25', false, 'JUDGEMENT', 'the issuer did not supply the receipt or a record of the correct amount', 'the issuer''s documents are in the case and include no copy of the receipt for this transaction and no other record showing what the correct amount was — the filing says only that the amount is wrong, or states the correct amount in the issuer''s or the cardholder''s own words with no receipt, bill, quote or order behind it — or the issuer''s attachments are general pages, such as a price list, an official fee page, a currency conversion or a bank or card-account screen, rather than a record of this purchase.', 'the issuer''s documents in the case, quoted or listed, showing no receipt and no record of the amount the cardholder says was correct.', 'the issuer''s documents include a copy of the receipt or another record of this purchase showing an amount — for example an invoice, an order or checkout page, a booking, ticket or itinerary receipt, a bill or folio, or an instalment plan — even one the merchant disputes, one in another currency, or one marked as a copy or transcription; the issuer''s documents are not in the case; or only the merchant says the issuer supplied nothing.', 10, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G15', 'PRECONDITION', 'VISA-12.5-11.9.4.1', 'Either: The Transaction amount is incorrect or an addition or transposition error occurred. For an ATM Transaction, the ATM Deposit Adjustment amount is incorrect.', 'ID', 'IDRC25', false, 'JUDGEMENT', 'the complaint is not about an incorrect amount and belongs under a different reason code', 'the issuer''s filing or the cardholder''s own words describe a complaint other than the amount charged being wrong — for example that the goods or services never arrived or were not as described, that an order was cancelled or a refund not given, that the cardholder does not recognise the charge, that they were charged twice, or that the charge was taken in the wrong currency — and say nothing about the amount charged differing from the amount of the sale, or about a total added up wrongly or digits swapped.', 'the issuer''s filing, quoted, describing the complaint as something other than the amount charged.', 'the filing or the cardholder''s own words say, even briefly, that the amount charged was more or less than the amount of the sale, the receipt, the bill or the agreed price, or that a total was added up wrongly or digits were swapped; the complaint names both a wrong currency and a wrong amount; or only the merchant characterises the complaint. A complaint that a travel or rental charge differs from the price quoted is the quoted-price argument, and one about a charge added after check-out or return is the after-completion argument.', 8, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G16', 'PRECONDITION', 'VISA-12.5-11.9.4.2', 'The Dispute amount is limited to the difference between the amounts.', 'ID', 'IDRC25', true, 'JUDGEMENT', 'the dispute claims more than the difference between the amounts', 'the issuer''s filing, the cardholder''s own words or a receipt the issuer attached show the amount the cardholder says should have been charged, and the issuer disputes the whole charge, or an amount its filing does not limit to the part said to be wrong — for example a tip or a single item said to be wrong while the whole bill is disputed.', 'the filing''s or the attached receipt''s statement of the amount the cardholder says was correct, beside the amount the issuer disputes and the amount processed shown in the transaction record.', 'nothing in the records shows what amount the cardholder says was correct; the filing states that only the part said to be overcharged is disputed; a refund the issuer has not deducted, which is the credit argument; the amount the cardholder says was correct is in a different currency from the amount processed or the amount disputed, so the two cannot be set side by side in one currency; or the complaint is that no part of the charge should have been made, which is not an amount complaint and may be the different-complaint argument.', 9, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G9', 'PRECONDITION', 'VISA-12.5-11.9.4.4', '120 calendar days from either: – The Transaction Processing Date', 'ID', 'IDRC25', false, 'TIME_LIMIT', 'raised beyond the time limit counted from the processing date', 'the time-limits section shows this limit as MET. Rely on the figures shown there; never count days yourself.', 'the system''s day count, cited by its bracketed field name.', 'the time-limits section shows it as NOT MET or NOT YET KNOWN.', 11, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G2', 'PRECONDITION', 'VISA-12.5-11.9.4.3', 'An ATM Cash Disbursement', 'ID', 'IDRC25', false, 'RECORD', 'ATM cash disbursement', 'the transaction-record section shows this exclusion as MET. Rely on the result shown there; never work it out yourself.', 'the record entry the section names, cited by its bracketed field name.', 'the section shows it as NOT MET.', 12, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G3', 'PRECONDITION', 'VISA-12.5-11.9.4.3', 'A Mobile Push Payment Transaction', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G4', 'PRECONDITION', 'VISA-12.5-11.9.4.3', 'A Straight Through Processing Transaction', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G10', 'PRECONDITION', 'VISA-12.5-11.9.4.4', '120 calendar days from either: – For an Adjustment of an ATM Cash Disbursement or a PIN-Authenticated Visa Debit Transaction, the Transaction Date of the Adjustment', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G12', 'PRECONDITION', 'VISA-12.5-11.9.4.5', 'For an ATM Transaction, certification of the correct ATM Deposit Adjustment amount', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '12.5'), 'G17', 'PRECONDITION', 'VISA-12.5-11.9.4.4', '120 calendar days from either: – The Transaction Processing Date of an ATM Deposit Adjustment', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G1', 'GROUND', 'VISA-13.2-11.10.3.6', 'A credit or Reversal issued by the Merchant was not addressed by the Issuer in the Dispute', 'CP', NULL, false, NULL, 'a credit or reversal already issued and not addressed in the dispute', 'the merchant''s records show a refund, credit or reversal of the disputed charge, in whole or in part — a payment-system line, a refund confirmation, a reversal record or a statement of refunds to the card — with its date and amount, and the record itself shows it refunds or reverses this charge rather than another charge in the series.', 'the merchant''s payment-system record of the refund, credit or reversal of this charge, showing its date, its amount, the card it went to and that it refunds or reverses the disputed charge, beside an issuer''s filing that disputes the amount without deducting it.', 'only an offer or promise to refund; a refund to a different card, a voucher or an account credit; a refund shown as pending, cancelled or rejected; a refund of an earlier or later charge in the series, or of a different purchase; the issuer''s filing already mentions the refund, credit or reversal, or the amount disputed is already reduced by it; no record of any refund, credit or reversal of this charge; or the refund is already deducted and the issuer disputes more than the unused part of the service, which is the unused-portion argument.', 1, 'ALL', 'CREDIT')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G11', 'GROUND', 'VISA-13.2-11.10.3.6', 'The Cardholder no longer disputes the Transaction', 'CNLD', NULL, false, NULL, 'the cardholder no longer disputes the transaction', 'the merchant''s records hold the cardholder''s own written words saying the matter is resolved; that they accept the charge or the renewal it paid for; that they want to keep or reinstate the service and go on paying for it; or that they are withdrawing the dispute.', 'a message from the cardholder, dated after the dispute was raised, saying in terms that they no longer dispute the charge.', 'the only records are the merchant''s own notes, call logs or summaries; a refund or credit record on its own, which is the credit argument; the cardholder''s words were written before the dispute was raised; the cardholder went on using the service but said nothing, which may be the used-after-withdrawal argument; or the cardholder accepts something but still asks for their money back.', 2, 'ALL', 'CARDHOLDER_WITHDREW')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G12', 'GROUND', 'VISA-13.2-11.10.3.6', 'The Cardholder requested cancellation for a different date and services were provided until this date1', 'NL', NULL, false, NULL, 'cancellation requested for a different date, with the service provided until that date', 'the cardholder''s own request to cancel — a message, a cancellation form, or a choice they made in their account — asks for the service to end on a date other than the one the issuer gives, for example at the end of the current billing period or contract term, or on a date the cardholder named; the disputed charge pays for service before that date; and the merchant''s records show the service provided or available to the cardholder up to that date.', 'the cardholder''s dated cancellation request naming the date it should take effect, with the merchant''s service or account record showing the service active and provided until that date and the period the disputed charge paid for.', 'the cardholder asked for the service to stop at once and only the merchant''s terms set a later date, which may be the billed-after-service argument; the disputed charge pays for service after the requested date; the service was stopped or withdrawn before that date; the only evidence of the requested date is the merchant''s own statement; or, in Europe, the issuer''s filing states that the account was closed, facilities were withdrawn or the cardholder died, or the records show the issuer advised the merchant of any of these.', 3, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G13', 'GROUND', 'VISA-13.2-11.10.3.6', 'The Merchant posts charges to Cardholders after services have been provided and that the Cardholder received services until the cancellation date1', 'NL', NULL, false, NULL, 'service billed after it was provided, and received until the cancellation date', 'the merchant''s terms or billing records show it charges for the service after providing it — at the end of each period, or for usage already made, such as a metered service or a membership billed in arrears — and its service records show the cardholder received the service up to the cancellation date, the last date the cardholder was allowed to use it, with the disputed charge paying for service in that period.', 'the billing terms the cardholder accepted, showing charges taken after each period of service, with the service or usage record for the period the disputed charge covers, running up to the cancellation date.', 'the merchant charges in advance for a coming period, which may be the different-date argument where the cardholder asked for the service to end later; the disputed charge pays for service after the cancellation date; the records do not show the service received in the period charged; or, in Europe, the issuer''s filing states that the account was closed, facilities were withdrawn or the cardholder died, or the records show the issuer advised the merchant of any of these.', 4, 'ALL', 'POLICY')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G14', 'GROUND', 'VISA-13.2-11.10.3.6', 'The Issuer’s claim is invalid that the Acquirer or Merchant was notified that the account was closed1', 'NL', NULL, false, NULL, 'the merchant was not notified that the account was closed', 'the issuer''s filing says the merchant or the acquirer was told that the cardholder''s account was closed before the charge was processed, and the merchant''s records bear on that claim — its complete record of notices received about this cardholder''s card, including any card-updating service it uses, showing no notice of closure before the charge, or showing the notice arrived only after the charge was processed.', 'the merchant''s dated record of every notice received about this cardholder''s card up to the charge, covering the route the issuer says it used, showing no notice of closure before the charge was processed — or the notice itself, dated after processing — and, where the record shows it, authorisations approved on the card after the date the issuer says the account was closed.', 'the records show the merchant received notice of the closure before the charge was processed; the records say nothing about the notices received; the issuer''s claim is that facilities were withdrawn or the cardholder died, rather than that the account was closed; the dispute is that the cardholder withdrew permission, not that the account was closed, which may be the different-date, billed-after-service or used-after-withdrawal argument; or, in Europe, the issuer''s filing states that the account was closed, facilities were withdrawn or the cardholder died, or the records show the issuer advised the merchant of any of these.', 6, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G15', 'GROUND', 'VISA-13.2-11.10.3.6', 'The Cardholder used services after the withdrawal of permission to bill date and prior to the Dispute Processing Date2', 'NL', NULL, false, NULL, 'the cardholder used the service after withdrawing permission to be billed', 'the merchant''s records show the cardholder used the service after the date they withdrew permission to be billed and before the dispute was raised — for example signed in, streamed, ordered, attended, received a delivery or made a booking under the subscription.', 'a record the service itself made at the time of use, dated after the last day the cardholder was allowed to use the service and inside the period the disputed charge pays for, showing the cardholder''s own account in use.', 'the records show no use after the withdrawal; the only use came after the dispute was raised; the activity was not the cardholder''s, such as an automatic background process with no action by the cardholder; or neither the issuer''s filing nor the merchant''s records show when the cardholder withdrew permission, so the use cannot be placed after it.', 5, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G2', 'PRECONDITION', 'VISA-13.2-11.10.3.2', 'The Dispute amount is limited to the unused portion of the service or merchandise.1', 'ID', 'IDRC25', true, 'JUDGEMENT', 'the dispute claims more than the unused portion of the service or merchandise', 'the records show the cardholder used part or all of the service in the period the disputed charge paid for — days of access, sessions, deliveries, bookings — or received and kept merchandise the charge paid for, and the dispute claims the full charge or otherwise appears to include the part that was used or kept.', 'the merchant''s usage, access or delivery records for the period the disputed charge paid for, showing what was used or kept, with the dates, beside the amount the issuer disputes.', 'nothing was used or kept in that period; the dispute is plainly limited to what was unused; a refund the issuer has not deducted, which is the credit argument; the records do not show what was used or kept; or, in Europe, the charge is an installment payment for a single purchase, to which this limit does not apply.', 13, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G3', 'PRECONDITION', 'VISA-13.2-11.10.3.3', 'A Mobile Push Payment Transaction', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G4', 'PRECONDITION', 'VISA-13.2-11.10.3.3', 'A Straight Through Processing Transaction', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G5', 'PRECONDITION', 'VISA-13.2-11.10.3.3', 'An Installment Transaction1', 'ID', 'IDRC25', false, 'JUDGEMENT', 'installment payment for a single purchase', 'the merchant''s records show the disputed charge is one payment in a series for a single purchase of goods or services — or the repayment of a single debt — agreed when the purchase was made, over a fixed period: for example an installment or pay-in-parts plan showing the total price, the number of payments and which payment this charge is.', 'the installment agreement the cardholder accepted for this purchase, showing the single purchase, its total price and the number, amounts and dates of the payments, with the merchant''s record that the disputed charge is one of them.', 'the charges pay for goods or services provided period by period for as long as the cardholder keeps them, such as a subscription or membership, which is a recurring charge; the records do not show a single purchase split into payments; or, in Europe, where an installment charge may be disputed under this reason code.', 7, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G6', 'PRECONDITION', 'VISA-13.2-11.10.3.3', 'An Unscheduled Credential-on-File Transaction', 'ID', 'IDRC25', false, 'JUDGEMENT', 'unscheduled charge to a card held on file', 'the merchant''s records show the disputed charge was taken from a card the cardholder had stored with the merchant, not on a set date or at a regular interval but when an event the cardholder agreed to occurred — for example an automatic top-up when a balance fell below a set level, or a charge for usage as it arose.', 'the stored-card agreement the cardholder accepted with this merchant, naming the event that prompts a charge, with the merchant''s record showing that event triggered this charge.', 'the charge was taken on a set date or at a regular interval, such as a monthly or annual subscription, which is a recurring charge; the cardholder made the payment themselves at the time, which is the cardholder-initiated argument; or the records do not show what prompted the charge.', 8, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G7', 'PRECONDITION', 'VISA-13.2-11.10.3.3', 'A Transaction that the Cardholder states is fraudulent', 'ID', 'IDRC25', false, 'JUDGEMENT', 'cardholder states the transaction is fraudulent, a different reason code', 'the issuer''s filing or the cardholder''s own words say the cardholder did not make, sign up for or agree to the purchase at all, or call it fraud or the use of their card by someone else — so the dispute belongs under a fraud reason code, not this one.', 'the words in the dispute filing saying the cardholder did not make or take part in the transaction, or in the sign-up behind it.', 'the cardholder acknowledges signing up for the subscription or service and says only that charges after they cancelled, or after a free trial or introductory offer ended, were not authorised or should not have been taken, which is the cancellation complaint itself; or only the merchant alleges fraud by the cardholder.', 10, 'ALL', 'FRAUD_CLAIM')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G8', 'PRECONDITION', 'VISA-13.2-11.10.3.3', 'A Cardholder-initiated Transaction', 'ID', 'IDRC25', false, 'JUDGEMENT', 'payment initiated by the cardholder', 'the merchant''s records show the cardholder started the disputed payment themselves at the time — for example paid at checkout while signed in, chose to renew or buy again and confirmed the payment, entered their card details for it, or paid in person — including the first payment made when signing up; or the transaction record shows the card was present, or its details were entered, for this payment, rather than a card held on file being charged.', 'the merchant''s session or order record for this payment showing the cardholder''s own action that started it, with its date and time — a sign-in and checkout, a confirmed renewal, card details entered — matching the disputed charge.', 'the merchant charged a card it held on file without the cardholder acting at the time, even though the cardholder had agreed to such charges in advance, which is the recurring charge this reason code is about; the cardholder''s only action was the original sign-up and the disputed charge is a later one; or the records do not show who started the payment.', 9, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G9', 'PRECONDITION', 'VISA-13.2-11.10.3.3', 'Effective for Disputes processed on or after 18 April 2026 A Transaction in which the Cardholder’s cancellation was after the date of the Transaction', 'ID', 'IDRC25', false, 'JUDGEMENT', 'cancellation made after the date of the transaction', 'the issuer''s filing gives the date the cardholder withdrew permission to be charged, or cancelled, and that date is later than the transaction date shown in the transaction record; or the cardholder''s dated cancellation request in the merchant''s records is later than that transaction date.', 'the issuer''s questionnaire, cited by page, giving a withdrawal or cancellation date later than the transaction date in the transaction record.', 'the withdrawal or cancellation date is on or before the transaction date; neither the issuer''s filing nor the merchant''s records give a date for it; or the only date given is the last day the cardholder was allowed to use the service rather than the date permission was withdrawn, where the two differ, which is open under S-120.', 12, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G16', 'PRECONDITION', 'VISA-13.2-11.10.3.1', 'The Cardholder withdrew permission to charge the Payment Credential for a Recurring Transaction or, in the Europe Region, an Installment Transaction.', 'ID', 'IDRC25', false, 'JUDGEMENT', 'no withdrawal of permission for a recurring charge', 'the issuer''s filing or the cardholder''s own words describe a complaint other than withdrawn permission or a closed account — for example that the cardholder does not recognise the charge, that the service was poor, or that the amount was wrong; or the merchant''s complete contact and account history for this subscription, across every route the cardholder could use to cancel, shows no request to cancel or stop the charges before the dispute; or the records show the disputed charge was a one-off charge, not one of a series of regular charges.', 'the issuer''s filing, quoted, showing the complaint is something other than a withdrawal of permission; or the merchant''s complete contact and account history for this subscription, covering every cancellation route its terms offered, showing no request to cancel or stop the charges.', 'the cardholder asked to cancel or stop the charges by any route, even one the terms did not offer, or asked the issuer to stop them; the request came after the disputed charge, which is the cancellation-after-the-transaction argument; the cardholder asked for the cancellation to take effect on a later date, which is the different-date argument; the dispute is that the merchant was told the account was closed, or in Europe that facilities were withdrawn or the cardholder died, which may be the closed-account argument; the records cover only some of the routes the cardholder could use, or say nothing about whether the cardholder cancelled; or the charge is an unscheduled charge, one the cardholder made themselves or, outside Europe, an installment, which are the unscheduled-charge, cardholder-initiated and installment arguments. A complaint about an unrecognised charge may also be the fraud argument.', 11, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G10', 'PRECONDITION', 'VISA-13.2-11.10.3.4', '120 calendar days from the Transaction Processing Date', 'ID', 'IDRC25', false, 'TIME_LIMIT', 'raised beyond the time limit counted from the processing date', 'the time-limits section shows this limit as MET. Rely on the figures shown there; never count days yourself.', 'the system''s day count, cited by its bracketed field name.', 'the time-limits section shows it as NOT MET or NOT YET KNOWN.', 14, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G18', 'PRECONDITION', 'VISA-13.2-11.10.3.5-EUROPE', 'Certification of any of the following:', 'ID', 'IDRC25', true, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.2'), 'G17', 'PRECONDITION', 'VISA-13.2-11.10.3.5', 'Certification of either:', 'ID', 'IDRC25', true, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G1', 'GROUND', 'VISA-13.3-11.10.4.6', 'A credit or Reversal issued by the Merchant was not addressed by the Issuer in the Dispute.', 'CP', NULL, false, NULL, 'a credit or reversal already issued and not addressed in the dispute', 'the merchant''s records show a refund, credit or reversal of this purchase, in whole or in part — a payment-system line, a refund confirmation, a reversal record or a statement of refunds to the card — with its date and amount, and the record itself shows it refunds or reverses the disputed transaction.', 'the merchant''s payment-system record of the refund, credit or reversal of this purchase, showing its date, its amount, the card it went to and that it refunds or reverses the disputed transaction, beside an issuer''s filing that disputes the amount without deducting it.', 'only an offer or promise to refund; a replacement, repair or exchange instead of money; a refund to a different card, a voucher or store credit; a refund shown as pending, cancelled or rejected; a refund of a different purchase; the issuer''s filing already mentions the refund, credit or reversal, or the amount disputed is already reduced by it; or no record of any refund, credit or reversal of this purchase. Where the refund is already deducted and the issuer still disputes more than the value of what was returned or left unused, that may be the amount argument.', 1, 'ALL', 'CREDIT')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G2', 'GROUND', 'VISA-13.3-11.10.4.6', 'The Cardholder no longer disputes the Transaction.', 'CNLD', NULL, false, NULL, 'the cardholder no longer disputes the transaction', 'the merchant''s records hold the cardholder''s own written words saying the matter is resolved; that they accept a repair, replacement, exchange or partial refund and are content; or that they are withdrawing the dispute.', 'a message from the cardholder, dated after the dispute was raised, saying in terms that they no longer dispute the charge.', 'the only records are the merchant''s own notes, call logs or summaries; a refund or credit record on its own, which is the credit argument; the cardholder''s words were written before the dispute was raised; or the cardholder accepts a repair, replacement or partial refund but still asks for their money back.', 2, 'ALL', 'CARDHOLDER_WITHDREW')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G3', 'GROUND', 'VISA-13.3-11.10.4.6', 'Both of the following: Evidence to prove that the merchandise or service matched what was described (including the description of the quality of the merchandise or service) or was not damaged or defective; Merchant rebuttal to the Cardholder’s claims', 'NL', NULL, false, NULL, 'the merchandise or services matched what was described and were not damaged or defective', 'the merchant''s records show what was described at the time of purchase — the listing, product page, receipt, order confirmation, contract or specification, or what the merchant told the cardholder — and that what was provided matched it, including any description of its quality; or, for a complaint of damage or a defect, the merchant''s records show that the merchandise was not damaged or defective when the cardholder received it — for example a despatch inspection or test record, photographs at despatch, or a carrier''s record of intact delivery — whether or not the records also show the description.', 'for a description complaint, the description as the cardholder had it at purchase for this item or service, beside a record of what was actually supplied — a despatch or inspection record, photographs at despatch, a test or service report, or an independent assessment; for damage or a defect, an inspection or test record for this item at despatch or on its return, or an independent assessment; in either case with the merchant''s own written answer to each thing the cardholder says was wrong.', 'for a complaint that what was received differed from its description, the records do not show what was described at purchase; for a complaint of damage or a defect, the records do not show the condition of the merchandise when it was supplied or received; the records show a difference between what was described and what was supplied; the merchant''s own records confirm the fault or damage; the merchant offers only a general statement that its goods or services are of good quality; or the complaint is not about what was received — for example that it never arrived, or that a cancellation or return was not refunded — which may be the argument that the complaint belongs under a different reason code. A complaint about the quality of food from a restaurant or café may also be the restaurant-food argument, and a complaint only about the price may be the price argument.', 6, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G4', 'GROUND', 'VISA-13.3-11.10.4.6', 'If applicable, evidence to prove that the Cardholder did not attempt to return the merchandise or certification that the returned merchandise has not been received', 'NL', NULL, false, NULL, 'the cardholder did not attempt to return the merchandise, or the returned merchandise was not received', 'the dispute concerns merchandise, and either the records show the cardholder kept it and made no attempt to send it back — the cardholder''s or the issuer''s own words, or the merchant''s complete returns and contact history for this order showing no return request — or the merchant''s returns records show that goods the cardholder says were sent back have not arrived.', 'the merchant''s returns record and its complete contact history for this order showing no return request, or the cardholder''s own words that they kept the goods; or, for goods said to be sent back, the merchant''s returns log for this order showing nothing received, beside any carrier or tracking reference the issuer gives.', 'the dispute concerns services only; the cardholder asked to return the goods and the merchant refused, refused a return label, told them not to send the goods back, did not respond, no longer exists, or gave no clear instructions on how to return; a carrier or tracking record shows the return delivered to the merchant; the returned goods are held by customs, which may be the customs argument; or nothing in the filing, the cardholder''s words or the merchant''s records raises a return at all. Part sent back and part kept may be the amount argument for the part kept, and goods kept with no attempt at all may also be the return-or-cancel argument.', 3, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G5', 'GROUND', 'VISA-13.3-11.10.4.6', 'For a Dispute where a travel agency using a Visa Commercial Card Virtual Account has a contractual agreement with a T&E Merchant that covers the terms for specified services, evidence to prove that the terms of service included in the contractual agreement were as described or honored by the Merchant', 'NL', NULL, false, NULL, 'the services matched the travel agency''s contract and the contract was honoured', 'the purchase was paid by a travel agency using a commercial virtual card under a contract with the merchant covering the services — for example a corporate rate or service agreement with a hotel, airline, cruise line or car rental company — and the merchant''s records show the services were provided as the contract sets out.', 'the contract or rate agreement setting out the terms of service, beside the merchant''s records of what was actually provided for this booking — the stay, the flight, the cruise or the rental — matching those terms.', 'no contract between the travel agency and the merchant covers the services; the payment was not made by a travel agency with a commercial virtual card, which may be the as-described argument; the records show a service the contract promised was not provided, or was provided differently; or the dispute concerns items the contract does not list, which may be the amount argument.', 4, 'ALL', 'POLICY')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G6', 'GROUND', 'VISA-13.3-11.10.4.6', 'For Transactions involving the acquisition of non-fiat currency (for example: cryptocurrency) or purchase of non-fungible token(s), evidence the non-fiat currency or non-fungible token(s) received by the Cardholder matches the non-fiat currency or non-fungible token(s) that was described at the time of the Transaction.', 'NL', NULL, false, NULL, 'the crypto or NFT received matched its description at the time of purchase', 'the purchase was of cryptocurrency or another non-fiat currency, or of an NFT, and the merchant''s records show that what the cardholder received — the asset, the quantity, the token — matches the description given at the time of purchase.', 'the order or confirmation for this purchase describing the asset, the quantity or the token, beside the transfer record — such as a blockchain transaction reference to the cardholder''s wallet — showing that same asset delivered.', 'the purchase was not crypto or an NFT; the complaint is that the asset fell in value or did not rise as expected, which is the resale-value argument; the asset was never delivered, or the cardholder lost access to it after delivery, which is a different reason code; or the records do not show what was described at purchase.', 5, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G7', 'PRECONDITION', 'VISA-13.3-11.10.4.1', 'One of the following: The merchandise or services did not match what was described on the Transaction Receipt, as specified in Section 5.9.2.2, Required Transaction Receipt Content for All Transactions or other record presented at the time of purchase. The merchandise received by the Cardholder was damaged or defective. The Cardholder disputes the quality of the merchandise or services received. For a Dispute where a travel agency using a Visa Commercial Card Virtual Account has a contractual agreement with a T&E Merchant that covers the terms for specified services, either: The Merchant failed to honor the contractual agreement. The services provided by the Merchant to the Virtual Account holder were not as described in the contractual agreement. For Transactions involving the acquisition of non-fiat currency or purchase of non-fungible token(s) (NFT), the non-fiat currency or non-fungible token received by the Cardholder did not match the description provided at the time of the Transaction.', 'ID', 'IDRC25', false, 'JUDGEMENT', 'the complaint belongs under a different reason code', 'the issuer''s filing or the cardholder''s own words show the complaint is about something other than what was received — for example that it never arrived, that a cancellation or return was not refunded, that the cardholder changed their mind or no longer wants it, that they do not recognise the charge, or that the amount was processed wrongly — and say nothing about it not matching its description, being damaged or defective, or being of poor quality.', 'the issuer''s filing, quoted, stating the complaint in terms that are not about the merchandise or service received.', 'the filing or the cardholder''s own words complain, even briefly, that what was received did not match what was described or what the merchant said, was damaged or defective, or was of poor quality, which the as-described argument answers; the complaint is a travel agency''s complaint that its contract was not honoured or its terms not met; the complaint is that crypto or an NFT received did not match its description; or only the merchant characterises the complaint. A charge the cardholder does not recognise may also be the fraud argument, and a complaint only about the price may be the price argument.', 14, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G10', 'PRECONDITION', 'VISA-13.3-11.10.4.5', 'An explanation of what was not as described or defective or information regarding the quality-related issue', 'ID', 'IDRC25', true, 'JUDGEMENT', 'insufficient explanation of what was not as described or defective', 'the issuer''s explanation of the dispute does not say what was wrong — only that the cardholder is unhappy or wants a refund, or that the purchase was not as described or faulty, with nothing about what was described, what was received instead, or what the fault or quality problem is.', 'the issuer''s explanation, quoted, showing it names no difference, fault or quality problem.', 'the explanation names what was described and what was received instead, or the fault, damage or quality problem, even briefly; the cardholder''s own letter or messages attached to the filing give that explanation; the explanation is blank, which is the missing-certification argument; or the dispute is a travel agency''s contract complaint whose explanation says how the contract was not honoured.', 20, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G13', 'PRECONDITION', 'VISA-13.3-11.10.4.3', 'A dispute regarding Value-Added Tax (VAT)', 'ID', 'IDRC25', false, 'JUDGEMENT', 'dispute about value-added tax', 'the issuer''s filing or the cardholder''s own words show the dispute is about VAT — the tax charged, the rate applied, the tax not refunded, or a refund made net of tax.', 'the words in the dispute filing naming VAT as what is disputed, with the receipt or invoice showing the tax figure the dispute concerns.', 'VAT is mentioned only as part of the total price disputed; the complaint is about what was received and VAT appears only in the amount claimed; or only the merchant mentions VAT.', 8, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G14', 'PRECONDITION', 'VISA-13.3-11.10.4.3', 'A Transaction in which the returned merchandise is held by any customs agency except the Merchant’s country’s customs agency', 'ID', 'IDRC25', false, 'JUDGEMENT', 'returned goods held by customs outside the merchant''s country', 'a carrier, tracking or customs record shows the goods the cardholder sent back to the merchant held by a customs agency, or awaiting customs clearance or duties, in any country other than the merchant''s, including the cardholder''s own, at or after the time the dispute was raised.', 'the return shipment''s tracking or customs record, dated on or after the day the dispute was raised, showing the hold and the country holding it, with the merchant''s address showing its own country.', 'the goods are held by the merchant''s own country''s customs; the hold is on the delivery to the cardholder, not the return; the goods have since been released, delivered or received back by the merchant; or the records do not show that the goods were sent back, which may be the no-return argument.', 9, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G16', 'PRECONDITION', 'VISA-13.3-11.10.4.3', 'A Transaction that the Cardholder states is fraudulent', 'ID', 'IDRC25', false, 'JUDGEMENT', 'cardholder states the transaction is fraudulent, a different reason code', 'the issuer''s filing or the cardholder''s own words say the cardholder did not make, take part in or agree to the purchase at all, or call it fraud or the use of their card by someone else — so the dispute belongs under a fraud reason code, not this one.', 'the words in the dispute filing saying the cardholder did not make or take part in the transaction.', 'the cardholder acknowledges making the purchase and complains about what they received, however strongly worded — for example that the listing was misleading or the goods not genuine — which is the complaint itself; or only the merchant alleges fraud by the cardholder.', 7, 'ALL', 'FRAUD_CLAIM')
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G18', 'PRECONDITION', 'VISA-13.3-11.10.4.3', 'A Dispute regarding the quality of food received from eating places or restaurants (for example: the burger was received cold)', 'ID', 'IDRC25', false, 'JUDGEMENT', 'dispute about the quality of food from an eating place', 'the issuer''s filing or the cardholder''s own words show the complaint is about the quality of food — cold, stale, undercooked, badly made or not as expected to eat — and the records show it came from a restaurant, café, takeaway or other place that prepares food to eat, whether eaten there, collected or delivered.', 'the cardholder''s or the issuer''s words describing what was wrong with the food, with the receipt or order showing the merchant is an eating place and what was ordered.', 'the complaint is that food or items were missing or never arrived, which is a different reason code; the complaint is about the service, the staff or the premises rather than the food; the food was bought from a shop rather than a place that prepares it to eat; or only the merchant describes the food''s quality. A quality complaint about anything other than food from an eating place is the dispute''s own reason, which the as-described argument answers.', 10, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G19', 'PRECONDITION', 'VISA-13.3-11.10.4.3', 'For a Transaction involving the acquisition of non-fiat currency (for example: cryptocurrency), or the purchase of non-fungible token(s) (NFT) in which the non-fiat currency or non-fungible token(s) does not increase in resale value as the Cardholder expected', 'ID', 'IDRC25', false, 'JUDGEMENT', 'crypto or NFT did not gain the resale value the cardholder expected', 'the purchase was of cryptocurrency or another non-fiat currency, or of an NFT, and the issuer''s filing or the cardholder''s own words show the complaint is that it did not rise in value, fell in value, or cannot be resold for what the cardholder expected.', 'the words in the dispute filing about the asset''s value or resale price, with the order for this purchase showing what was bought.', 'the merchant guaranteed that the asset would rise in value — in its listing, its terms or its messages to the cardholder; the complaint is that what was received did not match its description, which is the crypto-description argument; the asset was never delivered or the cardholder lost access to it, which is a different reason code; or the purchase was not crypto or an NFT.', 11, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G20', 'PRECONDITION', 'VISA-13.3-11.10.4.3', 'A Dispute regarding a price discrepancy', 'ID', 'IDRC25', false, 'JUDGEMENT', 'dispute about a price discrepancy', 'the issuer''s filing or the cardholder''s own words show the complaint is about the price — more than the cardholder expected, was quoted or saw advertised, a discount or offer not applied, or a lower price found elsewhere — rather than about the merchandise or service itself.', 'the words in the dispute filing that name the price as the problem, with the receipt or order showing the price the cardholder agreed to.', 'the complaint is that what was received did not match its description, was damaged or defective, or was of poor quality, and the price appears only as the amount the cardholder wants back, which the as-described argument answers; the amount charged differs from the receipt the cardholder accepted, which is a different reason code, which may be the argument that the complaint belongs under a different reason code; or only the merchant describes a price issue.', 12, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G21', 'PRECONDITION', 'VISA-13.3-11.10.4.2', 'The Dispute amount is limited to one of the following: The unused portion of the cancelled service; The value of the merchandise that the Cardholder returned or, if applicable, attempted to return; For a Dispute where a travel agency using a Visa Commercial Card Virtual Account has a contractual agreement with a T&E Merchant that covers the terms for specified services, the value of any items not listed in the contractual agreement', 'ID', 'IDRC25', true, 'JUDGEMENT', 'the dispute claims more than the value returned, unused or not covered by the contract', 'the records show the cardholder kept part or all of the merchandise without sending it back or making an attempt to return it that the rule counts, or used part of a service before cancelling it, or — for a travel agency''s contract — that the dispute includes items the contract lists, and the issuer disputes the full transaction amount or an amount its filing does not limit to what was returned, validly attempted to be returned, left unused or not listed in the contract.', 'the merchant''s returns, delivery or usage records for this purchase showing what was sent back and what was kept or used, with the dates, beside the amount the issuer disputes; for a travel agency''s contract, the contract''s list of items beside the items disputed.', 'nothing was kept or used; the goods were not sent back because the merchant refused the return, refused a return label, told the cardholder not to send them, did not respond, no longer exists or gave no clear instructions — an attempted return the rule counts, whose value is within the limit; the dispute is plainly limited to what was returned or left unused; a refund the issuer has not deducted, which is the credit argument; or the records do not show what was kept, used or listed.', 18, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G22', 'PRECONDITION', 'VISA-13.3-11.10.4.2', 'Before the Issuer may initiate a Dispute, the Cardholder must attempt to resolve1 the dispute with the Merchant or the Merchant’s liquidator.2', 'ID', 'IDRC25', true, 'JUDGEMENT', 'no attempt to resolve with the merchant', 'the issuer''s form states the cardholder did not attempt to resolve the dispute with the merchant, or the merchant, still trading and handling its own customer contact, holds a complete contact history for this order showing the cardholder''s first contact about the problem came after the dispute was raised.', 'the issuer''s form stating no attempt was made, or the merchant''s complete contact history for this order, with dates, showing no contact about the problem before the dispute.', 'the issuer''s form certifies an attempt to resolve, or the records show the cardholder contacted the merchant, its liquidator or anyone acting for it about the problem before the dispute, by any route, including a return or refund request; the cardholder cancelled the service, which counts as the attempt; the merchant is insolvent or in liquidation and the only support is the merchant''s own contact history, which would not show contact with a liquidator; the purchase was crypto or an NFT, which is the crypto resolution argument; the payment was made by a travel agency with a commercial virtual card under a contract covering the services; or the only support is the merchant''s statement that it received no complaint.', 16, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G23', 'PRECONDITION', 'VISA-13.3-11.10.4.2', 'Before the Issuer may initiate a Dispute, the Cardholder must return or attempt to return the merchandise or cancel the services.2,3 Attempt to return is only valid when the Merchant does one of the following: Refused the return of the merchandise; Refused to provide a return merchandise authorization/label; Instructed the Cardholder not to return the merchandise; Merchant no longer exists or is not responding to the Cardholder; Merchant did not provide clear instructions on how to return', 'ID', 'IDRC25', false, 'JUDGEMENT', 'the cardholder did not return the merchandise or cancel the services before disputing', 'the dispute concerns merchandise the cardholder received, or a service that could still be cancelled, and the records show that before the dispute the cardholder neither sent the goods back nor cancelled the service — the cardholder''s or the issuer''s own words that the goods were kept, or the merchant''s complete returns and contact history for this order showing no return or cancellation request — or that an attempted return was not one the rule counts, because the merchant offered a return, a return label or clear instructions and the cardholder did not send the goods.', 'the merchant''s complete returns and contact history for this order, with dates before the dispute, showing no return or cancellation request, or the cardholder''s own words that they kept the goods; or, for an attempted return, the merchant''s message to the cardholder giving a return label or clear return instructions, with no record of the goods being sent.', 'the records show the cardholder sent the goods back or cancelled the service before the dispute, even late; the merchant refused the return, refused a return label, told the cardholder not to send the goods back, did not respond, no longer exists, or gave no clear instructions; the returned goods are held by the merchant''s own country''s customs; the service had already been provided, which is the credit-request argument; the payment was made by a travel agency with a commercial virtual card under a contract covering the services; the only support is the merchant''s statement that nothing was returned; or the records say nothing about a return or cancellation. Goods kept with no attempt at all may also be the no-return argument.', 13, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G25', 'PRECONDITION', 'VISA-13.3-11.10.4.2', 'For Disputes related to services that have been rendered, the Cardholder must request a credit from the Merchant.', 'ID', 'IDRC25', true, 'JUDGEMENT', 'the cardholder did not ask the merchant for a credit for services already provided', 'the dispute concerns a service already provided — for example a stay, a repair, a treatment, a course or an installation — and the records show the cardholder did not ask the merchant for a refund or credit before the dispute: the issuer''s form or the cardholder''s own words saying so, or the merchant''s complete contact history for this order showing no request for a refund or credit before the dispute was raised.', 'the issuer''s form stating no credit was requested, or the merchant''s complete contact history for this order, with dates, showing the first request for a refund or credit came after the dispute was raised.', 'the cardholder asked the merchant for a refund or credit, in whole or in part, before the dispute, by any route; the service could still be cancelled, which is the return-or-cancel argument; the purchase was merchandise; the payment was made by a travel agency with a commercial virtual card under a contract covering the services; the only support is the merchant''s statement that it received no request; or the records say nothing about contact before the dispute.', 15, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G26', 'PRECONDITION', 'VISA-13.3-11.10.4.2', 'For a Dispute related to a Transaction involving the acquisition of non-fiat currency (for example: cryptocurrency) or purchase of a non-fungible token (NFT), both: – The Dispute amount is limited to the cost of the non-fiat currency or non-fungible token(s) the Cardholder intended to acquire or purchase at the time of the Transaction.', 'ID', 'IDRC25', true, 'JUDGEMENT', 'the dispute claims more than the crypto or NFT cost at the time of purchase', 'the purchase was of cryptocurrency or another non-fiat currency, or of an NFT, and the issuer''s filing shows the amount disputed rests on something other than what the asset cost at the time of purchase — for example its later market value or the gain the cardholder expected.', 'the order or confirmation showing what the asset cost at the time of purchase, beside the issuer''s filing stating the amount it disputes and how it was reached.', 'the purchase was not crypto or an NFT; the issuer disputes no more than what the asset cost at purchase; or the records do not show how the amount disputed was reached.', 19, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G27', 'PRECONDITION', 'VISA-13.3-11.10.4.2', 'For a Dispute related to a Transaction involving the acquisition of non-fiat currency (for example: cryptocurrency) or purchase of a non-fungible token (NFT), both: – Before the Issuer may initiate a Dispute, the Cardholder must attempt to resolve the Dispute with the Merchant, Ramp Provider or, its Conversion Affiliate as applicable.', 'ID', 'IDRC25', true, 'JUDGEMENT', 'no attempt to resolve a crypto or NFT purchase with the merchant or its ramp provider', 'the purchase was of cryptocurrency or another non-fiat currency, or of an NFT, and the issuer''s form states the cardholder did not attempt to resolve the dispute, or the complete contact history of the merchant, the ramp provider or the business it processed the purchase for shows the cardholder''s first contact about the problem came after the dispute was raised.', 'the issuer''s form stating no attempt was made, or the complete contact history of the merchant and the ramp provider for this purchase, with dates, showing no contact about the problem before the dispute.', 'the purchase was not crypto or an NFT, which is the general resolution argument; the issuer''s form certifies an attempt to resolve; the records show the cardholder contacted the merchant, the ramp provider or the business it processed for about the problem before the dispute, by any route; or the only support is one party''s statement that it received no complaint.', 17, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G8', 'PRECONDITION', 'VISA-13.3-11.10.4.4', 'A Dispute must be processed within either: – 120 calendar days of either: – The date the Cardholder3 received the merchandise or services4', 'ID', 'IDRC25', false, 'TIME_LIMIT', 'raised beyond the time limit counted from the date the purchase was received', 'the time-limits section shows this limit as MET. Rely on the figures shown there; never count days yourself.', 'the system''s day count, cited by its bracketed field name.', 'the time-limits section shows it as NOT MET or NOT YET KNOWN.', 22, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G29', 'PRECONDITION', 'VISA-13.3-11.10.4.4', 'Before initiating a Dispute, the Issuer must wait 15 calendar days1,2 from the date the Cardholder returned or attempted to return the merchandise or cancelled the services.', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G30', 'PRECONDITION', 'VISA-13.3-11.10.4.4', 'A Dispute must be processed within either: – 120 calendar days of either: – The Transaction Processing Date', 'ID', 'IDRC25', false, 'TIME_LIMIT', 'raised beyond the time limit counted from the processing date', 'the time-limits section shows this limit as MET. Rely on the figures shown there; never count days yourself.', 'the system''s day count, cited by its bracketed field name.', 'the time-limits section shows it as NOT MET or NOT YET KNOWN.', 21, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G31', 'PRECONDITION', 'VISA-13.3-11.10.4.4', 'Not to exceed 540 calendar days from the Transaction Processing Date', 'ID', 'IDRC25', false, 'TIME_LIMIT', 'raised beyond the outer time limit', 'the time-limits section shows this limit as MET. Rely on the figures shown there; never count days yourself.', 'the system''s day count, cited by its bracketed field name.', 'the time-limits section shows it as NOT MET or NOT YET KNOWN.', 23, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G9', 'PRECONDITION', 'VISA-13.3-11.10.4.5', 'Certification of the following, as applicable:', 'ID', 'IDRC25', true, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G11', 'PRECONDITION', 'VISA-13.3-11.10.4.3', 'An ATM Cash Disbursement', 'ID', 'IDRC25', false, 'RECORD', 'ATM cash disbursement', 'the transaction-record section shows this exclusion as MET. Rely on the result shown there; never work it out yourself.', 'the record entry the section names, cited by its bracketed field name.', 'the section shows it as NOT MET.', 24, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G15', 'PRECONDITION', 'VISA-13.3-11.10.4.3', 'The Cash-Back portion of a Visa Cash-Back Transaction', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G17', 'PRECONDITION', 'VISA-13.3-11.10.4.3', 'An Automated Fuel Dispenser Transaction', 'ID', 'IDRC25', false, 'RECORD', 'automated fuel dispenser transaction', 'the transaction-record section shows this exclusion as MET. Rely on the result shown there; never work it out yourself.', 'the record entry the section names, cited by its bracketed field name.', 'the section shows it as NOT MET.', 25, 'ALL', NULL)
