  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G12', 'PRECONDITION', 'VISA-13.3-11.10.4.3', 'A Straight Through Processing Transaction', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G24', 'PRECONDITION', 'VISA-13.3-11.10.4.2', 'Attempt to return is only valid when the Merchant does one of the following: Refused the return of the merchandise; Refused to provide a return merchandise authorization/label; Instructed the Cardholder not to return the merchandise; Merchant no longer exists or is not responding to the Cardholder; Merchant did not provide clear instructions on how to return', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement (reason_code_id, code, kind, anchor, requirement_text, response_reason, sub_form_code, supplementary, argument_class, label, nominate_when, strong_evidence, does_not_fit, render_order, region, role) VALUES
  ((SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3'), 'G28', 'PRECONDITION', 'VISA-13.3-11.10.4.2', 'For Transactions involving the acquisition of non-fiat currency (for example: cryptocurrency) or purchase of non-fungible token(s), the non-fiat currency or non-fungible token(s) was guaranteed to increase in value by the Merchant.', 'ID', 'IDRC25', false, NULL, NULL, NULL, NULL, NULL, NULL, 'ALL', NULL)
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND r.code = 'G22'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterTransactionProcessing'), 'GE', 541, ARRAY['expectedDate']::text[], '541 or more days', 'In addition, the dispute was raised {n} calendar days after the transaction processing date, beyond the 540-day outer time limit for this reason code.', 'The transaction was processed on {processDate} and the dispute was processed on {reportedDate}, {n} calendar days later, beyond the 540-calendar-day outer time limit.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND r.code = 'G25'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterServiceCancellation'), 'LE', 29, ARRAY['mccIsAgency','cancellationKnown','bankruptNotYes']::text[], '29 or fewer days', 'In addition, the dispute was raised {n} calendar days after the service provider cancelled, within the 30-day waiting period that applies to travel and ticket agencies.', 'The merchant is a travel agency (merchant category code 4722). The issuer''s questionnaire gives {cancellationDate} as the date the service was cancelled ({fx}) and {bk}. The dispute was processed on {reportedDate}, {n} calendar days later, inside the 30-calendar-day waiting period that applies to travel and ticket agencies.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND r.code = 'G26'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterServiceCancellation'), 'LE', 29, ARRAY['mccIsAgency','cancellationKnown','notBondedInsolvency']::text[], '29 or fewer days', 'In addition, the dispute was raised {n} calendar days after the merchant cancelled, within the 30-day waiting period that applies to travel and ticket agencies.', 'The merchant is a travel agency (merchant category code 4722). The issuer''s questionnaire gives {cancellationDate} as the date the merchant cancelled ({fx}), and the records do not show an insolvent provider whose services were covered by a bonding or insurance scheme. The dispute was processed on {reportedDate}, {n} calendar days later, inside the 30-calendar-day waiting period that applies to travel and ticket agencies.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND r.code = 'G32'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterTransactionProcessing'), 'GE', 121, ARRAY['noExpectedDate','coveredNotYes']::text[], '121 or more days', 'In addition, the dispute was raised {n} calendar days after the transaction processing date, beyond the 120-day time limit for this reason code.', 'The transaction was processed on {processDate} and the dispute was processed on {reportedDate}, {n} calendar days later. The issuer''s questionnaire specifies no expected delivery or service date ({fx}). The dispute was therefore initiated after the 120-calendar-day time limit.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND r.code = 'G33'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterExpectedReceiptDate'), 'GE', 121, ARRAY['expectedDate','coveredNotYes']::text[], '121 or more days', 'In addition, the dispute was raised {n} calendar days after the last date the cardholder expected to receive the merchandise or services, beyond the 120-day time limit for this reason code.', 'The issuer''s questionnaire gives {expectedDate} as the last date the cardholder expected to receive the merchandise or services ({fx}). The dispute was processed on {reportedDate}, {n} calendar days later, after the 120-calendar-day time limit.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND r.code = 'G23'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterBondingLetterOrAdvice'), 'GE', 61, ARRAY['coveredByScheme']::text[], '61 or more days', 'In addition, the dispute was processed {n} calendar days after the date of the letter or advice from the bonding authority or insurance scheme, beyond the 60-day time limit that applies where a reimbursement claim was required.', 'The issuer''s documents show the services covered by a bonding authority or insurance scheme and give {letterDate} as the date of the scheme''s letter or advice ({fx}). The dispute was processed on {reportedDate}, {n} calendar days later, after the 60-calendar-day time limit that applies where a reimbursement claim was required.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND r.code = 'G34'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterTransactionDate'), 'LE', 14, ARRAY['noExpectedDate','bankruptNotYes']::text[], '14 or fewer days', 'In addition, the dispute was raised {n} calendar days after the transaction date, within the 15-day waiting period that applies where no expected date was given.', 'The transaction took place on {saleDate} and the dispute was processed on {reportedDate}, {n} calendar days later. The issuer''s questionnaire specifies no expected delivery or service date ({fx}) and {bk}. The dispute was therefore initiated inside the required 15-calendar-day waiting period.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND r.code = 'G36'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterServiceCancellation'), 'LE', 14, ARRAY['cancellationKnown','mccNotAgency','bankruptNotYes']::text[], '14 or fewer days', 'In addition, the dispute was raised {n} calendar days after the merchant cancelled, within the required 15-day waiting period.', 'The issuer''s questionnaire gives {cancellationDate} as the date the merchant cancelled ({fx}) and {bk}. The dispute was processed on {reportedDate}, {n} calendar days later, inside the required 15-calendar-day waiting period.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND r.code = 'G27'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterBondingClaimSubmitted'), 'LE', 59, ARRAY['coveredByScheme','schemeInsufficientNotYes']::text[], '59 or fewer days', 'In addition, the dispute was raised {n} calendar days after the reimbursement claim was submitted to the bonding authority or insurance scheme, inside the 60-day waiting period the rule requires.', 'The issuer''s documents show the services covered by a bonding authority or insurance scheme and give {claimDate} as the date the reimbursement claim was submitted to the scheme ({fx}), and do not state that the scheme is insufficient. The dispute was processed on {reportedDate}, {n} calendar days later, inside the required 60-calendar-day waiting period.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND r.code = 'G42'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterExpectedReceiptDate'), 'LT', 0, ARRAY['bankruptNotYes']::text[], 'below 0 days (raised before the expected date)', 'In addition, the dispute was raised {n} calendar days before the date the cardholder expected to receive the merchandise or services, and the issuer''s filing gives no reason for disputing early.', 'The issuer''s questionnaire gives {expectedDate} as the date the cardholder expected to receive the merchandise or services ({fx}) and {bk}. The dispute was processed on {reportedDate}, {n} calendar days before that date, and the filing gives no explanation for initiating the dispute early.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7') AND r.code = 'G14'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterTransactionProcessing'), 'GE', 121, ARRAY['noReceivedOrExpectedDate']::text[], '121 or more days', 'In addition, the dispute was raised {n} calendar days after the transaction processing date, beyond the 120-day time limit for this reason code.', 'The transaction was processed on {processDate} and the dispute was processed on {reportedDate}, {n} calendar days later. The issuer''s questionnaire gives no date, on or after the transaction processing date, on which the cardholder received or expected to receive the merchandise or services ({fx}). The dispute was therefore initiated after the 120-calendar-day time limit.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7') AND r.code = 'G20'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterReceivedOrExpectedDate'), 'GE', 121, ARRAY['receivedOrExpectedDate']::text[], '121 or more days', 'In addition, the dispute was raised {n} calendar days after the date the cardholder received or expected to receive the merchandise or services, beyond the 120-day time limit for this reason code.', 'The issuer''s questionnaire gives {expectedDate} as the date the cardholder received or expected to receive the merchandise or services ({fx}). The dispute was processed on {reportedDate}, {n} calendar days later, after the 120-calendar-day time limit.');
INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.7') AND r.code = 'G21'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterTransactionProcessing'), 'GE', 661, ARRAY['receivedOrExpectedDate']::text[], '661 or more days', 'In addition, the dispute was raised {n} calendar days after the transaction processing date; with the date of receipt or expected receipt capped at 540 days after processing, the 120-day time limit for this reason code ended 660 days after processing.', 'The transaction was processed on {processDate} and the dispute was processed on {reportedDate}, {n} calendar days later. The date on which the cardholder received or expected to receive the merchandise or services counts as no later than 540 calendar days after processing, so the 120-calendar-day time limit ended no later than 660 calendar days after processing.');
