INSERT INTO wdp_ai.requirement_time_limit (requirement_id, day_count_fact_key_id, compare_op, day_limit, conditions, limit_text, filing_sentence, letter_paragraph) VALUES
  ((SELECT r.id FROM wdp_ai.requirement r WHERE r.reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3') AND r.code = 'G30'), (SELECT id FROM wdp_ai.fact_key WHERE key = 'dispute.daysAfterTransactionProcessing'), 'GE', 121, ARRAY['noReceivedDate','negotiationWindowClosed']::text[], '121 or more days', 'In addition, the dispute was raised {n} calendar days after the transaction processing date, beyond the 120-day time limit for this reason code.', 'The transaction was processed on {processDate} and the dispute was processed on {reportedDate}, {n} calendar days later. The issuer''s questionnaire gives no date, on or after the transaction processing date, on which the cardholder received the merchandise or services, and shows no ongoing negotiations with the merchant that would bring the dispute within the time limit ({fx}). The dispute was therefore initiated after the 120-calendar-day time limit.');
