-- a key the document no longer carries goes, unless a stored fact still names it
DELETE FROM wdp_ai.fact_key WHERE key NOT IN ('transaction.posEnvironment', 'dispute.daysAfterTransactionProcessing', 'dispute.daysAfterTransactionDate', 'dispute.daysAfterExpectedReceiptDate', 'dispute.daysAfterServiceCancellation', 'dispute.daysAfterBondingClaimSubmitted', 'dispute.daysAfterBondingLetterOrAdvice', 'transaction.mcc', 'transaction.channel', 'transaction.entryMode', 'transaction.cashBackAmount', 'transaction.merchantCountry', 'issuer.certifiesCardholderCancelledPriorToExpectedDate', 'cardholder.expectedReceiptDate', 'issuer.certifiesMerchantInsolvent', 'issuer.certifiesMerchantCancelled', 'issuer.merchantCancellationDate', 'issuer.certifiesNonFiatNotDeliveredToWallet', 'cardholder.attemptedResolutionWithMerchant', 'travel.servicesCoveredByBondingOrInsuranceScheme', 'bonding.reimbursementClaimSubmitted', 'bonding.reimbursementClaimSubmittedDate', 'bonding.schemeInsufficient', 'bonding.letterOrAdviceDate', 'dispute.daysAfterReceivedOrExpectedDate', 'issuer.receivedOrExpectedDate', 'dispute.daysAfterReceivedDate', 'issuer.receivedDate', 'issuer.negotiationsBeganDate', 'issuer.firstNotifiedDate')
  AND id NOT IN (SELECT fact_key_id FROM wdp_ai.extracted_fact);

-- requirements (§1-§10), upserted on (reason code, code); render orders parked first so a re-ordering cannot collide
UPDATE wdp_ai.requirement SET render_order = render_order + 1000
 WHERE reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.1') AND render_order IS NOT NULL;
