DELETE FROM wdp_ai.requirement WHERE reason_code_id = (SELECT id FROM wdp_ai.reason_code WHERE network = 'VISA' AND code = '13.3')
  AND code NOT IN ('G1', 'G2', 'G4', 'G5', 'G6', 'G3', 'G16', 'G13', 'G14', 'G18', 'G19', 'G20', 'G23', 'G7', 'G25', 'G22', 'G27', 'G21', 'G26', 'G10', 'G30', 'G8', 'G31', 'G29', 'G11', 'G17', 'G15', 'G9', 'G24', 'G12', 'G28');

-- the time-limit rules (§18): one row per TIME_LIMIT argument; absence means not a time limit

-- the record rules (§18): one row per RECORD argument, calculated by the orchestrator and shown to the model

-- the keys linked to the reason code (§18): the issuer-form keys, the bonding keys (EUROPE, CL-148), the day counts, the record fields; the region says on which cases the issuer-facts reader asks a DOCUMENT key

-- the forms (§19.1): the base forms first, then the sub-forms that name them

-- the fields of each form (§19.2), in display order

-- the value-only options (§19.3), by field name; a NULL reason code is every reason code of the network

COMMIT;
